type PushEnvironment = Record<string, string | undefined>;

export function repositoryEnvironment(env: PushEnvironment = process.env): PushEnvironment {
  // Git exports repository selectors inside hooks. A cwd alone does not
  // override them, so bind local archive commands to their explicit root.
  return Object.fromEntries(Object.entries(env).filter(([name]) => !name.startsWith("GIT_")));
}

export function pushedCommit(env: PushEnvironment): string | null {
  // The hook is deliberately inactive for tags, other branches, deletions,
  // and manual `prek run` invocations without actual push metadata.
  if (env.PRE_COMMIT_REMOTE_BRANCH !== "refs/heads/main") return null;
  const commit = env.PRE_COMMIT_TO_REF;
  if (!commit || /^0+$/.test(commit)) return null;
  if (!/^[a-f0-9]{40}$|^[a-f0-9]{64}$/.test(commit)) {
    throw new Error("The pre-push hook did not supply a valid commit ID.");
  }
  return commit;
}

async function command(args: string[], cwd: string): Promise<string> {
  const child = Bun.spawn(args, {
    cwd, stdout: "pipe", stderr: "pipe",
    env: args[0] === "git" ? repositoryEnvironment() : process.env,
  });
  const [stdout, stderr, status] = await Promise.all([
    new Response(child.stdout).text(),
    new Response(child.stderr).text(),
    child.exited,
  ]);
  if (status !== 0) {
    // Do not echo authentication material, URLs with query strings, or
    // arbitrary provider logs into the Git hook's output.
    const reason = /not logged in|unauthorized|authentication/i.test(stderr)
      ? " Authenticate with Railway on this machine first."
      : " Inspect the named stage and Railway deployment dashboard.";
    throw new Error(`${args[0]} ${args[1]} failed (exit ${status}).${reason}`);
  }
  return stdout;
}

async function validatePublicTree(root: string): Promise<void> {
  for (const entry of await readdir(root, { withFileTypes: true })) {
    const file = join(root, entry.name);
    if (entry.isSymbolicLink() || (await lstat(file)).isSymbolicLink()) {
      throw new Error("Public deployment cannot include symbolic links.");
    }
    if (/^\.env(?:\.|$)/.test(entry.name) || /\.(pem|key|p12|sqlite)$/.test(entry.name)) {
      throw new Error("Unexpected private-file type in public deployment.");
    }
    if (entry.isDirectory()) await validatePublicTree(file);
  }
}

export async function createSnapshot(root: string, commit: string): Promise<string> {
  const resolved = (await command(["git", "rev-parse", "--verify", `${commit}^{commit}`], root)).trim();
  if (resolved !== commit) throw new Error("Deploy an exact commit ID, not a mutable ref.");
  // Keep the archive under the repo root for Railway's path-as-root behavior.
  // It is never assembled from the dirty working tree.
  const tempRoot = join(root, ".local");
  await mkdir(tempRoot, { recursive: true });
  const snapshot = await mkdtemp(join(tempRoot, "railway-public-"));
  try {
    const archive = Bun.spawn(["git", "archive", "--format=tar", commit, "--", ...PUBLIC_PATHS], {
      cwd: root, stdout: "pipe", stderr: "pipe", env: repositoryEnvironment(),
    });
    const bytes = await new Response(archive.stdout).arrayBuffer();
    if (await archive.exited !== 0) throw new Error("The pushed commit is missing required public source files.");
    const extract = Bun.spawn(["tar", "-xf", "-", "-C", snapshot], {
      stdin: new Blob([bytes]), stdout: "pipe", stderr: "pipe",
    });
    if (await extract.exited !== 0) throw new Error("Could not extract the committed public snapshot.");
    await validatePublicTree(snapshot);
    await cp(join(snapshot, "apps/docs"), join(snapshot, "apps/landing/developers"), { recursive: true });
    await cp(join(snapshot, "infra/railway/landing.railway.json"), join(snapshot, "railway.json"));
    await mkdir(join(snapshot, "apps/landing/.well-known"), { recursive: true });
    await writeFile(join(snapshot, "apps/landing/.well-known/deployment.json"), JSON.stringify({ commit }) + "\n");
    return snapshot;
  } catch (error) {
    await rm(snapshot, { recursive: true, force: true });
    throw error;
  }
}

type Deployment = { id: string; status: string };

export function deploymentStatus(deployments: Deployment[], id: string): string | null {
  return deployments.find((deployment) => deployment.id === id)?.status ?? null;
}

async function verifyPublicCommit(commit: string): Promise<void> {
  const response = await fetch(`${RAILWAY_TARGET.url}/.well-known/deployment.json`, {
    cache: "no-store", signal: AbortSignal.timeout(15_000),
  });
  if (!response.ok || (await response.json() as { commit?: string }).commit !== commit) {
    throw new Error("Public deployment marker does not match the pushed commit.");
  }
  for (const path of ["/", "/healthz", "/investors", "/services", "/terms", "/privacy", "/downloads/notorganic-terms-of-service.pdf", "/downloads/notorganic-privacy-policy.pdf"]) {
    const result = await fetch(`${RAILWAY_TARGET.url}${path}`, { signal: AbortSignal.timeout(15_000) });
    await result.body?.cancel();
    if (!result.ok) throw new Error(`Public check failed: ${path} returned ${result.status}.`);
  }
  const docs = "https://docs.notorganic.info";
  const marker = await fetch(`${docs}/.well-known/deployment.json`, { cache: "no-store", signal: AbortSignal.timeout(15_000) });
  if (!marker.ok || (await marker.json() as { commit?: string }).commit !== commit) {
    throw new Error("Docs deployment marker does not match the pushed commit.");
  }
  for (const path of ["/", "/authentication", "/api", "/billing", "/data", "/operations"]) {
    const response = await fetch(`${docs}${path}`, { signal: AbortSignal.timeout(15_000) });
    await response.body?.cancel();
    if (!response.ok) throw new Error(`Docs check failed: ${path} returned ${response.status}.`);
  }
  const identity = "https://id.notorganic.info";
  const identityMarker = await fetch(`${identity}/.well-known/deployment.json`, { cache: "no-store", signal: AbortSignal.timeout(15_000) });
  if (!identityMarker.ok || (await identityMarker.json() as { commit?: string }).commit !== commit) {
    throw new Error("Identity frontend marker does not match the pushed commit.");
  }
  for (const product of ["notorganic", "keating", "twyne", "interleave", "stich"]) {
    const page = await fetch(`${identity}/?product=${product}&theme=dark`, { signal: AbortSignal.timeout(15_000) });
    await page.body?.cancel();
    if (!page.ok || !page.headers.get("set-cookie")?.includes(`notorganic_appearance=${product}:dark;`)) {
      throw new Error(`Identity appearance handoff failed for ${product}.`);
    }
  }
  const session = await fetch(`${identity}/api/session`, { signal: AbortSignal.timeout(15_000) });
  await session.body?.cancel();
  if (session.status !== 401) throw new Error("Unauthenticated identity session check must return 401.");
  const metadata = await fetch(`${identity}/client-metadata.json`, { signal: AbortSignal.timeout(15_000) });
  if (!metadata.ok || (await metadata.json() as { client_id?: string }).client_id !== `${identity}/client-metadata.json`) {
    throw new Error("Identity OAuth metadata proxy check failed.");
  }

}

export async function deploy(root: string, commit: string): Promise<void> {
  console.log(`Railway: preparing public source at ${commit.slice(0, 12)}.`);
  const snapshot = await createSnapshot(root, commit);
  let stage = "upload";
  try {
    const target = ["--project", RAILWAY_TARGET.project, "--service", RAILWAY_TARGET.service, "--environment", RAILWAY_TARGET.environment];
    const upload = await command(["railway", "up", snapshot, "--path-as-root", "--no-gitignore", ...target,
      "--detach", "--message", `Public website and docs from main ${commit}`], root);
    const id = upload.match(/[?&]id=([a-f0-9-]{36})/)?.[1];
    if (!id) throw new Error("Upload returned no deployment ID; inspect Railway before retrying.");
    console.log(`Railway deployment ${id}; waiting for health checks.`);
    stage = "build and health checks";
    const deadline = Date.now() + 10 * 60_000;
    let lastStatus: string | null = null;
    while (Date.now() < deadline) {
      const deployments = JSON.parse(await command(["railway", "deployment", "list", ...target, "--limit", "20", "--json"], root)) as Deployment[];
      const status = deploymentStatus(deployments, id);
      if (status !== lastStatus) {
        console.log(`Railway: ${status ?? "waiting for deployment record"}.`);
        lastStatus = status;
      }
      if (["FAILED", "CRASHED", "REMOVED", "SKIPPED", "CANCELED"].includes(status ?? "")) {
        throw new Error(`Deployment ${id} ended with ${status}.`);
      }
      if (status === "SUCCESS") {
        stage = "public verification";
        // Allow the edge a short interval to switch to the new deployment.
        let lastError: unknown;
        for (let attempt = 0; attempt < 6; attempt++) {
          try {
            await verifyPublicCommit(commit);
            console.log(`Verified ${RAILWAY_TARGET.url} at ${commit.slice(0, 12)}.`);
            return;
          } catch (error) { lastError = error; }
          await Bun.sleep(5_000);
        }
        throw lastError;
      }
      await Bun.sleep(5_000);
    }
    throw new Error("Timed out waiting for Railway; deployment may still be running.");
  } catch (error) {
    const detail = error instanceof Error ? error.message : "Unknown error";
    throw new Error(`Railway ${stage} failed: ${detail}`);
  } finally {
    await rm(snapshot, { recursive: true, force: true });
  }
}

if (import.meta.main) {
  try {
    const commit = pushedCommit(process.env);
    if (commit) await deploy(resolve(import.meta.dir, ".."), commit);
    else console.log("Railway: no update to refs/heads/main; skipped.");
  } catch (error) {
    console.error(error instanceof Error ? error.message : "Railway deployment failed.");
    console.error("Push stopped. Railway may already have deployed; compare the public commit marker before retrying.");
    process.exitCode = 1;
  }
}
