} from "./http-evolution-runner";
import { OpenBaoTransit } from "./openbao";
import { NoopTelemetry, PostHogTelemetry } from "./telemetry";
import { tabularConfigFromEnv } from "./tabular";
import { extractionConfigFromEnv } from "./extraction";
import { type ModelAlias } from "@notorganic/contracts";
import { parsePublicClientProductCatalog } from "./public-client-product";
import type { GatewayConfig, Product } from "./types";
import { loadTractionConfig } from "./traction-config";
import { ConvexTractionStore } from "./traction-store";
import { knowledgeFromEnv } from "../../knowledge/config";
import { agentsFromEnv } from "../../agents/config";
import { productAssertionKeysFromEnv } from "./product-assertion-keys";
import { nativeProviderSelection } from "./native-provider-selection";
import { UnisonConfigurationStore } from "./unison-configuration";
import { ProviderErasureWorker } from "./provider-erasure-worker";
import { UnisonFinanceWorker } from "./unison-finance";
import { createUnisonMetadataMigration } from "./unison-achievement-migration";
import { stripeConnectFromEnv } from "./stripe-connect-config";
import { StripeConnectCommerce } from "./stripe-connect";
import { ConvexStripeConnectStore } from "./stripe-connect-store";

function required(name: string): string {
  const value = Bun.env[name]?.trim();
  if (!value) throw new Error(`${name} is required`);
  return value;
}

function json<T>(name: string): T {
  try {
    return JSON.parse(required(name)) as T;
  } catch (error) {
    throw new Error(`${name} must contain valid JSON`, { cause: error });
  }
}

function optionalJson<T>(name: string): T | undefined {
  const value = Bun.env[name]?.trim();
  if (!value) return undefined;
  try {
    return JSON.parse(value) as T;
  } catch (error) {
    throw new Error(`${name} must contain valid JSON`, { cause: error });
  }
}

function optionalNonnegativeInteger(name: string): number | undefined {
  const value = Bun.env[name]?.trim();
  if (!value) return undefined;
  const parsed = Number(value);
  if (!Number.isSafeInteger(parsed) || parsed < 0) {
    throw new Error(`${name} must be a non-negative integer`);
  }
  return parsed;
}

function corsAllowedOrigins(): string[] {
  const value = Bun.env.CORS_ALLOWED_ORIGINS?.trim();
  if (!value) return [];
  const origins = value.split(",").map((origin) => origin.trim());
  for (const origin of origins) {
    let parsed: URL;
    try {
      parsed = new URL(origin);
    } catch (error) {
      throw new Error(
        `CORS_ALLOWED_ORIGINS contains an invalid origin: ${origin}`,
        {
          cause: error,
        },
      );
    }
    if (
      origin === "*" ||
      (parsed.protocol !== "https:" && parsed.protocol !== "http:") ||
      parsed.origin !== origin
    ) {
      throw new Error(
        `CORS_ALLOWED_ORIGINS must contain exact http(s) origins without paths: ${origin}`,
      );
    }
  }
  return [...new Set(origins)];
}

function publicClientProducts(): Record<string, Product> {
  const configured =
    optionalJson<Record<string, string>>("PUBLIC_CLIENT_PRODUCT_CATALOG") ?? {};
  const catalog: Record<string, string> = {
    "https://stich.cc": "stich",
    ...configured,
  };
  return parsePublicClientProductCatalog(catalog);
}

function signingKeys(): GatewayConfig["productAssertionKeys"] {
  return productAssertionKeysFromEnv(Bun.env);
}

interface PaddleCatalogEntry {
  product: Product;
  grantProgram: string;
}

const paddleCatalog =
  optionalJson<Record<string, PaddleCatalogEntry>>("PADDLE_PRICE_CATALOG") ??
  {};
const paddleApiKey =
  Object.keys(paddleCatalog).length > 0
    ? required("PADDLE_API_KEY")
    : Bun.env.PADDLE_API_KEY?.trim() || undefined;

const transit = new OpenBaoTransit({
  address: required("OPENBAO_ADDR"),
  token: Bun.env.OPENBAO_TOKEN,
  roleId: Bun.env.OPENBAO_ROLE_ID,
  secretId: Bun.env.OPENBAO_SECRET_ID,
  keyName: Bun.env.OPENBAO_TRANSIT_KEY ?? "provider-responses",
});

const syncTransit = new OpenBaoTransit({
  address: required("OPENBAO_ADDR"),
  token: Bun.env.OPENBAO_TOKEN,
  roleId: Bun.env.OPENBAO_ROLE_ID,
  secretId: Bun.env.OPENBAO_SECRET_ID,
  keyName: Bun.env.OPENBAO_SYNC_TRANSIT_KEY ?? "account-sync",
});

const convexStore = new ConvexProviderStore({
  convexUrl: required("CONVEX_URL"),
  gatewaySecret: required("CONVEX_GATEWAY_SECRET"),
  transit,
  syncTransit,
  paddleApiKey,
  paddleBaseUrl: Bun.env.PADDLE_BASE_URL,
  paddleCheckoutUrl: Bun.env.PADDLE_CHECKOUT_URL,
  paddleGrantPrograms: Object.fromEntries(
    Object.entries(paddleCatalog).map(([productId, entry]) => [
      productId,
      entry.grantProgram,
    ]),
  ),
});

const convexAchievements = new ConvexAchievementStore({
  convexUrl: required("CONVEX_URL"),
  gatewaySecret: required("CONVEX_GATEWAY_SECRET"),
});
const nativeSelection = nativeProviderSelection({ env: Bun.env, backend: convexStore, achievements: convexAchievements, transit });
const store = nativeSelection.store;

const evolutionRunnerConfigs =
  HttpEvolutionRunnerEnvironmentConfigListSchema.parse(
    optionalJson<unknown>("EVOLUTION_HTTP_RUNNERS") ?? [],
  );
const evolutionRunners = new AccountEvolutionRunnerRegistry();
for (const runner of evolutionRunnerConfigs) {
  evolutionRunners.register(
    new HttpEvolutionRunner({
      id: runner.id,
      endpoint: runner.endpoint,
      capabilities: runner.capabilities,
      authorizationToken: required(runner.authorizationTokenEnv),
      requestTimeoutMs: runner.requestTimeoutMs,
      maximumResponseBytes: runner.maximumResponseBytes,
    }),
  );
}
const evolutionBlobs = new FilesystemEvolutionBlobPlane(
  Bun.env.EVOLUTION_BLOB_ROOT?.trim() ||
    (Bun.env.NODE_ENV === "production" ? required("EVOLUTION_BLOB_ROOT") : resolve(".local/evolution-artifacts")),
);
const accountEvolution = new AccountEvolutionService({
  store: nativeSelection.authority
    ? new UnisonAccountEvolutionStore(nativeSelection.authority)
    : new ConvexAccountEvolutionStore({
        convexUrl: required("CONVEX_URL"),
        gatewaySecret: required("CONVEX_GATEWAY_SECRET"),
      }),
  blobs: evolutionBlobs,
  runners: evolutionRunners,
  attestationVerifier: new EvolutionEd25519AttestationVerifier({
    keys: evolutionRunnerConfigs.map((runner) => ({
      runnerId: runner.id,
      keyId: runner.attestationKeyId,
      publicJwk: runner.attestationPublicJwk as JWK,
    })),
  }),
});

const pseudonymSecret = Buffer.from(
  required("PROVIDER_PSEUDONYM_SECRET"),
  "base64",
);
if (pseudonymSecret.byteLength < 32) {
  throw new Error("PROVIDER_PSEUDONYM_SECRET must decode to at least 32 bytes");
}

let tavus: GatewayConfig["tavus"];
if (
  ["TAVUS_API_KEY", "TAVUS_PAL_ID", "TAVUS_INTERLEAVE_PAL_ID", "TAVUS_TERMINATION_SECRET"].some((name) =>
    Bun.env[name]?.trim(),
  )
) {
  const terminationSecret = Buffer.from(
    required("TAVUS_TERMINATION_SECRET"),
    "base64",
  );
  if (terminationSecret.byteLength < 32) {
    throw new Error(
      "TAVUS_TERMINATION_SECRET must decode to at least 32 bytes",
    );
  }
  tavus = {
    apiKey: required("TAVUS_API_KEY"),
    palId: Bun.env.TAVUS_PAL_ID?.trim() || Bun.env.TAVUS_KEATING_PAL_ID?.trim() || "",
    terminationSecret,
  };
}

function configuredPrice(name: string): number | undefined {
  const raw = Bun.env[name]?.trim();
  if (!raw) return undefined;
  const value = Number(raw);
  if (!Number.isSafeInteger(value) || value <= 0) throw new Error(`${name} must be a positive integer in microUSD`);
  return value;
}
if (tavus) {
  const products: NonNullable<GatewayConfig["tavus"]>["products"] = {};
  for (const product of ["keating", "interleave"] as const) {
    const prefix = `TAVUS_${product.toUpperCase()}`;
    const palId = Bun.env[`${prefix}_PAL_ID`]?.trim() || (product === "keating" ? tavus.palId : undefined);
    const minutePrice = configuredPrice(`${prefix}_PRICE_PER_MINUTE_MICROUSD`);
    if (palId && minutePrice) products[product] = {
      palId, pricePerMinuteMicrousd: minutePrice,
      conversationName: Bun.env[`${prefix}_CONVERSATION_NAME`]?.trim() || (product === "interleave" ? "Interleave Couple Coach" : "Keating Live with KeatingBot"),
      maxParticipants: Number(Bun.env[`${prefix}_MAX_PARTICIPANTS`] || (product === "interleave" ? "3" : "2")) as 2 | 3,
      maxDurationSeconds: Number(Bun.env[`${prefix}_MAX_DURATION_SECONDS`] || (product === "keating" ? "3600" : "1200")),
      model: Bun.env[`${prefix}_MODEL`]?.trim() || undefined,
    };
  }
  tavus.products = products;
}
const keenableSearchPrice = configuredPrice("KEENABLE_SEARCH_PRICE_MICROUSD");
const keenableFetchPrice = configuredPrice("KEENABLE_FETCH_PRICE_MICROUSD");
const keenable: GatewayConfig["keenable"] = Bun.env.KEENABLE_API_KEY?.trim() ? {
  apiKey: required("KEENABLE_API_KEY"), searchPriceMicrousd: keenableSearchPrice, fetchPriceMicrousd: keenableFetchPrice, hourlyLimit: configuredPrice("KEENABLE_HOURLY_LIMIT"),
} : undefined;
const video: GatewayConfig["video"] = Bun.env.FAL_KEY?.trim() ? { apiKey: required("FAL_KEY"), models: {} } : undefined;
for (const [alias, prefix, fallback, imageField] of [
  ["video", "VIDEO", "fal-ai/kling-video/v3/pro/image-to-video", "start_image_url"],
  ["video-fast", "VIDEO_FAST", "fal-ai/kling-video/v3/turbo/standard/image-to-video", "image_url"],
] as const) {
  const secondPrice = configuredPrice(`${prefix}_PRICE_PER_SECOND_MICROUSD`);
  if (video && secondPrice) video.models[alias] = { model: Bun.env[`${prefix}_UPSTREAM_MODEL`]?.trim() || fallback, pricePerSecondMicrousd: secondPrice, textModel: Bun.env[`${prefix}_TEXT_UPSTREAM_MODEL`]?.trim() || fallback.replace("image-to-video", "text-to-video"), imageField: Bun.env[`${prefix}_IMAGE_FIELD`]?.trim() === "start_image_url" ? "start_image_url" : Bun.env[`${prefix}_IMAGE_FIELD`]?.trim() === "image_url" ? "image_url" : imageField };
}

const typesafe: GatewayConfig["typesafe"] = Bun.env.TYPESAFE_API_KEY?.trim()
  ? { apiKey: required("TYPESAFE_API_KEY"), model: Bun.env.TYPESAFE_MODEL?.trim() || "jev-latest" }
  : undefined;

const traction = loadTractionConfig(Bun.env);
if (traction) traction.store = new ConvexTractionStore({ convexUrl: required("CONVEX_URL"), gatewaySecret: required("CONVEX_GATEWAY_SECRET") });

const config: GatewayConfig = {
  traction,
  store,
  gatewayIssuer: required("PROVIDER_ISSUER"),
  gatewayAudience: Bun.env.PROVIDER_AUDIENCE ?? "notorganic",
  gatewaySigningPrivateJwk: json<JWK>("PROVIDER_SIGNING_PRIVATE_JWK"),
  gatewaySigningPublicJwk: json<JWK>("PROVIDER_SIGNING_PUBLIC_JWK"),
  productAssertionKeys: signingKeys(),
  portkeyApiKey: required("PORTKEY_API_KEY"),
  portkeyBaseUrl: Bun.env.PORTKEY_BASE_URL,
  portkeyProvider: Bun.env.PORTKEY_OPENAI_PROVIDER,
  portkeyConfig: Bun.env.PORTKEY_CONFIG,
  ...(Bun.env.OPENAI_LIVE_API_KEY?.trim()
    ? {
        live: {
          apiKey: required("OPENAI_LIVE_API_KEY"),
          upstreamMicrousdPerMinute:
            optionalNonnegativeInteger("OPENAI_LIVE_MICROUSD_PER_MINUTE"),
          upstreamMicrousdPerSecond:
            optionalNonnegativeInteger("OPENAI_LIVE_MICROUSD_PER_SECOND"),
          products: {
            interleave: {
              alternativeModel: Bun.env.OPENAI_LIVE_INTERLEAVE_ALTERNATIVE_MODEL?.trim() || undefined,
              customVoiceIds: Bun.env.OPENAI_LIVE_INTERLEAVE_CUSTOM_VOICE_IDS
                ?.split(",").map(value => value.trim()).filter(Boolean),
            },
          },
        },
      }
    : {}),
  billingCheckoutEnabled: !!paddleApiKey,
  pseudonymSecret,
  pricingVersion: RETAIL_PRICING_VERSION,
  maxAllowedCostMicrousd: Math.max(...Object.values(ADMIN_CAPS_MICROUSD)),
  paddlePriceIds: {
    twyne: Object.entries(paddleCatalog)
      .filter(([, entry]) => entry.product === "twyne")
      .map(([id]) => id),
    keating: Object.entries(paddleCatalog)
      .filter(([, entry]) => entry.product === "keating")
      .map(([id]) => id),
    interleave: Object.entries(paddleCatalog)
      .filter(([, entry]) => entry.product === "interleave")
      .map(([id]) => id),
    baste: Object.entries(paddleCatalog)
      .filter(([, entry]) => entry.product === "baste")
      .map(([id]) => id),
    stich: Object.entries(paddleCatalog)
      .filter(([, entry]) => entry.product === "stich")
      .map(([id]) => id),
    // Normally empty: the portal links out to the owning product for top-ups,
    // and an empty allowlist makes portal-initiated checkout fail closed.
    notorganic: Object.entries(paddleCatalog)
      .filter(([, entry]) => entry.product === "notorganic")
      .map(([id]) => id),
  },
  paddlePricesByGrantProgram: Object.fromEntries(
    (["twyne", "keating", "interleave", "stich", "baste", "notorganic"] as const).map(
      (product) => [
        product,
        Object.fromEntries(
          Object.entries(paddleCatalog)
            .filter(([, entry]) => entry.product === product)
            .map(([productId, entry]) => [entry.grantProgram, productId]),
        ),
      ],
    ),
