function base64url(input: string | Uint8Array): string {
  const bytes =
    typeof input === "string" ? new TextEncoder().encode(input) : input;
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary).replace(/=/g, "").replace(/\+/g, "-").replace(/\//g, "_");
}

function decodeBase64(value: string): Uint8Array {
  const binary = atob(value.replace(/\s/g, ""));
  return Uint8Array.from(binary, (character) => character.charCodeAt(0));
}

async function loadPrivateKey(value: string): Promise<CryptoKey> {
  const trimmed = value.trim();
  if (trimmed.startsWith("{")) {
    return crypto.subtle.importKey(
      "jwk",
      JSON.parse(trimmed),
      { name: "Ed25519" },
      false,
      ["sign"],
    );
  }
  const encoded = trimmed.includes("BEGIN PRIVATE KEY")
    ? trimmed
        .replace("-----BEGIN PRIVATE KEY-----", "")
        .replace("-----END PRIVATE KEY-----", "")
    : trimmed;
  return crypto.subtle.importKey(
    "pkcs8",
    decodeBase64(encoded),
    { name: "Ed25519" },
    false,
    ["sign"],
  );
}

export function notOrganicEnabled(
  env: Readonly<Record<string, string | undefined>> = process.env,
): boolean {
  const value = env.NOTORGANIC_ENABLED?.trim().toLowerCase();
  return value === "1" || value === "true";
}

export function notOrganicIssuer(
  env: Readonly<Record<string, string | undefined>> = process.env,
): string {
  return (env.NOTORGANIC_ISSUER ?? NOTORGANIC_DEFAULT_ISSUER).replace(
    /\/$/,
    "",
  );
}

export function notOrganicOpenAiRoute(
  token: NotOrganicAccessToken,
  alias: NotOrganicModelAlias,
  feature: string,
  issuer = NOTORGANIC_DEFAULT_ISSUER,
  fetchImpl: typeof fetch = fetch,
  options: { readonly maxCostMicrousd?: number } = {},
): NotOrganicOpenAiRoute {
  if (!token.accessToken)
    throw new Error("A provider access token is required");
  if (!feature.trim()) throw new Error("A feature is required");
  const configuredBudget = notOrganicGenerationBudgetMicrousd(
    options.maxCostMicrousd ??
      process.env.NOTORGANIC_GENERATION_MAX_COST_MICROUSD,
  );
  // A token claim can only tighten the approved application limit. The gateway
  // independently verifies the token and still enforces its own alias caps.
  const ceiling = tokenBudgetCeiling(token.accessToken);
  const maxCostMicrousd = Math.min(
    configuredBudget,
    ceiling ?? configuredBudget,
    NOTORGANIC_ALIAS_CEILINGS_MICROUSD[alias],
  );
  return {
    baseURL: `${issuer.replace(/\/$/, "")}/v1`,
    apiKey: token.accessToken,
    model: alias,
    headers: {
      "x-notorganic-product": NOTORGANIC_PRODUCT,
      "x-notorganic-feature": feature,
    },
    fetch: createMeteredDpopFetch(token, maxCostMicrousd, fetchImpl),
  };
}

function createMeteredDpopFetch(
  token: NotOrganicAccessToken,
  maxCostMicrousd: number,
  fetchImpl: typeof fetch,
): typeof fetch {
  const fallbackGenerationId = crypto.randomUUID();
  const authenticatedFetch = createDpopFetch(token, fetchImpl);
  return (async (input: RequestInfo | URL, init?: RequestInit) => {
    const request = new Request(input, init);
    request.signal.throwIfAborted();
    const headers = new Headers(request.headers);
    const generationId =
      headers.get(NOTORGANIC_GENERATION_ID_HEADER) ?? fallbackGenerationId;
    if (!/^[A-Za-z0-9_-]{1,128}$/.test(generationId)) {
      throw new Error("Invalid logical generation request identifier.");
    }
    // SDK retries retain this ID and body. Tool steps change the body; separate
    // generateText invocations receive distinct IDs even with identical prompts.
    const prefix = new TextEncoder().encode(
      JSON.stringify([
        generationId,
        request.method,
        request.url,
        maxCostMicrousd,
      ]),
    );
    const body = new Uint8Array(await request.clone().arrayBuffer());
    const bytes = new Uint8Array(prefix.length + body.length);
    bytes.set(prefix);
    bytes.set(body, prefix.length);
    const digest = new Uint8Array(await crypto.subtle.digest("SHA-256", bytes));
    const key = Array.from(digest, (byte) =>
      byte.toString(16).padStart(2, "0"),
    ).join("");
    headers.delete(NOTORGANIC_GENERATION_ID_HEADER);
    headers.set("idempotency-key", `twyne_${key}`);
    headers.set("x-notorganic-max-cost-microusd", String(maxCostMicrousd));
    request.signal.throwIfAborted();
    return authenticatedFetch(new Request(request, { headers }));
  }) as typeof fetch;
}

export async function createDpopKeyPair(): Promise<DpopKeyPair> {
  const pair = await crypto.subtle.generateKey(
    { name: "ECDSA", namedCurve: "P-256" },
    true,
    ["sign", "verify"],
  );
  return {
    privateKey: pair.privateKey,
    publicJwk: await crypto.subtle.exportKey("jwk", pair.publicKey),
  };
}

async function accessTokenHash(accessToken: string): Promise<string> {
  const digest = await crypto.subtle.digest(
    "SHA-256",
    new TextEncoder().encode(accessToken),
  );
  return base64url(new Uint8Array(digest));
}

export class JudgementGateway {
  constructor(private readonly config: GatewayConfig) {}

  /**
   * Reserve against the account, call TypeSafe, settle on real token usage.
   *
   * Settlement always runs: on an upstream failure the reservation is
   * released rather than left holding credit, and a response that arrives
   * without usage is reconciled at the reserved ceiling rather than billed at
   * zero. Both are the same discipline `PortkeyProxy` applies.
   */
  async evaluate(
    principal: VerifiedPrincipal,
    body: unknown,
    idempotencyKey: string,
    requestHash: string,
  ): Promise<JudgementResult> {
    const request = validated(body);
    let backend = resolveDecisionBackend(this.config, request.model);
    compatible(request, backend);
    const loaders = await Promise.all((request.images ?? []).map(prepareRepresentationImage));
    const fallbackName = request.allow_fallback ? this.config.decisions?.fallback?.[backend.backend] : undefined;
    let fallbackBackend: ResolvedDecisionBackend | undefined;
    if (fallbackName && fallbackName !== backend.backend) {
      try {
        const candidate = resolveDecisionBackend(this.config, `judgement-${fallbackName}`);
        compatible(request, candidate); fallbackBackend = candidate;
      } catch (error) {
        if (!(error instanceof GatewayError)) throw error;
      }
    }
    let fallback: JudgementFallback | undefined;
    let requestId: string = crypto.randomUUID();
    const maxCostMicrousd = estimateMicrousd(request, backend) + (fallbackBackend ? estimateMicrousd(request, fallbackBackend) : 0);
    if (
      maxCostMicrousd >
      Math.min(
        principal.maxCostMicrousd,
        this.config.maxAllowedCostMicrousd ?? Number.MAX_SAFE_INTEGER,
      )
    ) {
      throw new GatewayError(
        402,
        "insufficient_quota",
        "The judgement exceeds the request budget.",
        "budget_exceeded",
      );
    }

    const reservation = await this.config.store.reserve({
      requestId,
      idempotencyKey,
      orgContext: principal.orgContext, agentContext: principal.agentContext, sessionVersion: principal.sessionVersion,
      accountId: principal.accountId,
      product: principal.product,
      feature: "judgement",
      alias: request.model ?? JUDGEMENT_ALIAS,
      maxCostMicrousd,
      pricingVersion: this.config.pricingVersion ?? "v1",
      requestHash,
    });
    if (reservation.status === "settled" && reservation.response) {
      const { model, answers, usage, fallback } = reservation.response;
      return { model, answers, usage, ...(fallback ? { fallback } : {}) } as JudgementResult;
    }
    if (reservation.status !== "reserved") {
      throw new GatewayError(
        409,
        "conflict_error",
        "This judgement request has already been submitted.",
        "idempotency_conflict",
      );
    }
    requestId = reservation.requestId;

    try {
      if (loaders.length) request.images = await Promise.all(loaders.map(load => load()));
    } catch (error) {
      await this.config.store.release({ requestId, reason: 'image_preparation_failed' });
      throw error;
    }

    try {
      await this.config.store.markDispatched({ requestId });
    } catch (error) {
      await this.config.store.release({
        requestId,
        reason: "dispatch_not_started",
      });
      throw error;
    }

    let response: Response;
    try {
      response = await this.#fetch(backend, request);
      // Only explicit overload rejections are eligible. Never repeat ambiguous delivery or accepted work.
      if ([429, 529].includes(response.status) && fallbackBackend) {
        fallback = { from: `judgement-${backend.backend}/${backend.model}`, to: `judgement-${fallbackBackend.backend}/${fallbackBackend.model}`, reason: `upstream_${response.status}` };
        backend = fallbackBackend;
        response = await this.#fetch(backend, request);
      }
    } catch {
      await this.config.store.reconcile({
        requestId,
        conservativeCostMicrousd: maxCostMicrousd,
        reason: "judgement_delivery_unknown",
      });
      throw new GatewayError(
        502,
        "api_error",
        "The judgement provider could not be reached.",
        "judgement_unreachable",
      );

