// Only globally routable addresses. IPv4-mapped IPv6 is rejected as well.
export function publicAddress(address: string): boolean {
  const ip = address.toLowerCase().replace(/^\[|\]$/g, "");
  if (isIP(ip) === 4) {
    const [a = 0, b = 0, c = 0] = ip.split(".").map(Number);
    return !(a === 0 || a === 10 || a === 127 || a >= 224 || a === 169 && b === 254 || a === 172 && b >= 16 && b <= 31 || a === 192 && (b === 168 || b === 0 && [0, 2].includes(c) || b === 88 && c === 99) || a === 100 && b >= 64 && b <= 127 || a === 198 && ([18, 19].includes(b) || b === 51 && c === 100) || a === 203 && b === 0 && c === 113);
  }
  return isIP(ip) === 6 && /^[23][0-9a-f]{3}:/.test(ip) && !ip.startsWith("2001:db8:") && !(/^2001:/.test(ip) && Number.parseInt(ip.split(":")[1] || "0", 16) < 0x200) && !ip.startsWith("2002:") && !ip.startsWith("3fff:");
