export async function publicUrl(config: GatewayConfig, value: unknown): Promise<URL> {
  if (typeof value !== "string" || value.length > 4096) invalid("A bounded HTTPS URL is required.");
  let url: URL; try { url = new URL(value); } catch { invalid("Invalid URL."); }
  if (url.protocol !== "https:" || url.username || url.password || url.port && url.port !== "443") invalid("Only public HTTPS URLs on port 443 are accepted.");
  const hostname = url.hostname.replace(/^\[|\]$/g, "");
  let addresses: string[];
  try { addresses = isIP(hostname) ? [hostname] : config.webResolve ? await config.webResolve(hostname) : (await lookup(hostname, { all: true })).map(x => x.address); }
  catch { invalid("URL host could not be verified."); }
  if (!addresses.length || addresses.some(ip => !publicAddress(ip))) invalid("Private, loopback and reserved targets are blocked.");
  url.hash = ""; return url;
}
