import { mutationGeneric, queryGeneric } from "convex/server";
import { v } from "convex/values";
import { now, requireGatewaySecret } from "./lib";
import { publicProfileForSession } from "./publicProfile";
import { resolveOrgAccess } from "./organizations";

export const health = queryGeneric({
  args: { serviceSecret: v.string() },
  handler: async (_ctx, args) => {
    requireGatewaySecret(args.serviceSecret);
    return { ok: true };
  },
});

export const account = queryGeneric({
  args: { serviceSecret: v.string(), did: v.string() },
  returns: v.object({ account: v.any(), products: v.array(v.any()), subscriptions: v.array(v.any()) }),
  handler: async (ctx, args) => {
    requireGatewaySecret(args.serviceSecret);
    const [account, products, subscriptions, oauthSession] = await Promise.all([
      ctx.db.query("didAccounts").withIndex("by_did", (q) => q.eq("did", args.did)).unique(),
      ctx.db.query("productMappings").withIndex("by_did_product", (q) => q.eq("did", args.did)).take(100),
      ctx.db.query("subscriptions").withIndex("by_did", (q) => q.eq("did", args.did)).take(100),
      ctx.db.query("oauthSessions").withIndex("by_did", (q) => q.eq("did", args.did)).unique(),
    ]);
    const profile = account?.deletedAt == null && oauthSession
      ? publicProfileForSession(oauthSession.publicProfile, args.did, oauthSession.sessionJson) : null;
    return { account: profile ? { ...account, did: args.did, ...profile } : account, products, subscriptions };
  },
});

export const wallet = queryGeneric({
  args: { serviceSecret: v.string(), did: v.string(), product: v.optional(v.string()) },
  handler: async (ctx, args) => {
    requireGatewaySecret(args.serviceSecret);
    const wallet = await ctx.db.query("wallets").withIndex("by_did", (q) => q.eq("did", args.did)).unique();
    const grants = await ctx.db.query("grantLots").withIndex("by_did_expiry", (q) => q.eq("did", args.did)).take(256);
    const active = grants.filter((lot) => (lot.expiresAt === null || lot.expiresAt > now())
      && (!args.product || lot.productScope === null || lot.productScope === args.product));
    const subscriptions = (await ctx.db.query("subscriptions")
      .withIndex("by_did", (q) => q.eq("did", args.did)).take(100))
      .filter((row) => !args.product || row.product === args.product)
      .map(({ plan, product, status, currentPeriodStart, currentPeriodEnd }) => ({
        plan, product, status, currentPeriodStart, currentPeriodEnd,
      }));
    const availableGrantMicros = active.reduce((sum, lot) => sum + lot.remainingMicros, 0);
    // Credit only one product can spend (Twyne's welcome lot, an admin grant
    // scoped to Twyne). The portal reads the wallet as product "notorganic",
    // which no product-scoped lot matches, so without this an account funded
    // only with scoped grants showed $0.00 while its product kept spending.
    const scopedGrantMicros: Record<string, number> = {};
    for (const lot of grants) {
      if (lot.productScope === null || (lot.expiresAt !== null && lot.expiresAt <= now())) continue;
      scopedGrantMicros[lot.productScope] = (scopedGrantMicros[lot.productScope] ?? 0) + lot.remainingMicros;
    }
    return {
      currency: "USD_MICROS",
      subscriptions,
      balanceMicros: wallet?.balanceMicros ?? 0,
      reservedMicros: wallet?.reservedMicros ?? 0,
      debtMicros: wallet?.debtMicros ?? 0,
      availableGrantMicros,
      scopedGrantMicros,
      availableMicros: (wallet?.debtMicros ?? 0) > 0 ? 0
        : Math.max(0, (wallet?.balanceMicros ?? 0) - (wallet?.reservedMicros ?? 0)) + availableGrantMicros,
      hostedInferenceBlocked: (wallet?.debtMicros ?? 0) > 0,
    };
  },
});

export const usage = queryGeneric({
  args: { serviceSecret: v.string(), did: v.string(), limit: v.number() },
  handler: async (ctx, args) => {
    requireGatewaySecret(args.serviceSecret);
    return await ctx.db
      .query("inferenceRequests")
      .withIndex("by_did_created", (q) => q.eq("did", args.did))
      .order("desc")
      .take(Math.min(Math.max(Math.trunc(args.limit), 1), 100));
  },
});

export const consumeDpopProof = mutationGeneric({
  args: { serviceSecret: v.string(), jti: v.string(), expiresAtSeconds: v.number() },
  handler: async (ctx, args) => {
    requireGatewaySecret(args.serviceSecret);
    const currentSeconds = Math.floor(now() / 1000);
    if (!args.jti || args.expiresAtSeconds <= currentSeconds || args.expiresAtSeconds > currentSeconds + 600) {
      throw new Error("INVALID_DPOP_EXPIRY");
    }
    const existing = await ctx.db.query("dpopProofs").withIndex("by_jti", (q) => q.eq("jti", args.jti)).unique();
    if (existing) return false;
    await ctx.db.insert("dpopProofs", {
      jti: args.jti,
      expiresAt: args.expiresAtSeconds * 1000,
      consumedAt: now(),
    });
    return true;
  },
});

async function responseOwner(ctx: any, response: any, args: { did: string; orgId?: string }) {
  if (response?.ownerKind !== "org") return response && !args.orgId && response.did === args.did;
  if (!args.orgId || response.orgId !== args.orgId) return false;
  const request = await ctx.db.query("inferenceRequests").withIndex("by_request", (q: any) => q.eq("requestId", response.requestId)).unique();
  if (!request || request.orgId !== args.orgId) return false;
  return (await resolveOrgAccess(ctx, { did: args.did, orgId: request.orgId, product: request.product })).allowed;
}

export const putResponse = mutationGeneric({
  args: {
    requestId: v.string(),
    serviceSecret: v.string(),
    responseId: v.string(),
    did: v.string(),
    ciphertext: v.string(),
    keyVersion: v.string(),
    aadHash: v.string(),
    expiresAt: v.number(),
  },
  handler: async (ctx, args) => {
    requireGatewaySecret(args.serviceSecret);
    const request = await ctx.db.query("inferenceRequests").withIndex("by_request", (q) => q.eq("requestId", args.requestId)).unique();
    if (!request || request.did !== args.did || request.state !== "succeeded") throw new Error("RESPONSE_REQUEST_INVALID");
    const prior = await ctx.db
      .query("encryptedResponses")
      .withIndex("by_response", (q) => q.eq("responseId", args.responseId))
      .unique();
    if (prior && prior.did !== args.did) throw new Error("RESPONSE_ID_CONFLICT");
    if (prior) return prior._id;
    return await ctx.db.insert("encryptedResponses", {
      requestId: args.requestId,
      responseId: args.responseId,
      did: args.did,
      ownerKind: request.orgId ? "org" : "personal",
      ...(request.orgId ? { orgId: request.orgId } : {}),
      ciphertext: args.ciphertext,
      keyVersion: args.keyVersion,
      algorithm: "OPENBAO-TRANSIT",
      aadHash: args.aadHash,
      createdAt: now(),
      expiresAt: args.expiresAt,
    });
  },
});

export const getResponse = queryGeneric({
  args: { serviceSecret: v.string(), did: v.string(), orgId: v.optional(v.id("organizations")), responseId: v.string() },
  handler: async (ctx, args) => {
    requireGatewaySecret(args.serviceSecret);
    const response = await ctx.db
      .query("encryptedResponses")
      .withIndex("by_response", (q) => q.eq("responseId", args.responseId))
      .unique();
    return response && await responseOwner(ctx, response, args) && response.expiresAt > now() ? response : null;
  },
});

export const responseForRequest = queryGeneric({
  args: { serviceSecret: v.string(), did: v.string(), orgId: v.optional(v.id("organizations")), requestId: v.string() },
  handler: async (ctx, args) => {
    requireGatewaySecret(args.serviceSecret);
    const response = await ctx.db
      .query("encryptedResponses")
      .withIndex("by_request", (q) => q.eq("requestId", args.requestId))
      .unique();
    return response && await responseOwner(ctx, response, args) && response.expiresAt > now() ? response : null;
  },
});

export const deleteResponse = mutationGeneric({
  args: { serviceSecret: v.string(), did: v.string(), orgId: v.optional(v.id("organizations")), responseId: v.string() },
  handler: async (ctx, args) => {
    requireGatewaySecret(args.serviceSecret);
    const response = await ctx.db
      .query("encryptedResponses")
      .withIndex("by_response", (q) => q.eq("responseId", args.responseId))
      .unique();
    if (!response || !await responseOwner(ctx, response, args)) return false;
    await ctx.db.delete(response._id);
    return true;
  },
});

export const recordRealtimeConsent = mutationGeneric({
  args: {
    serviceSecret: v.string(),
    did: v.string(),
    purpose: v.literal("portkey-realtime-content-logging"),
    policyVersion: v.literal("realtime-content-logging-v1"),
    granted: v.boolean(),
    source: v.string(),
  },
  handler: async (ctx, args) => {
    requireGatewaySecret(args.serviceSecret);
    const { serviceSecret: _secret, ...record } = args;
    await ctx.db.insert("consents", { ...record, recordedAt: now() });
  },
});

export const hasRealtimeConsent = queryGeneric({
  args: { serviceSecret: v.string(), did: v.string() },
  handler: async (ctx, args) => {
    requireGatewaySecret(args.serviceSecret);
    const records = await ctx.db
      .query("consents")
      .withIndex("by_did_purpose", (q) => q.eq("did", args.did))
      .order("desc")
      .take(100);
    return records.find((record) => record.purpose === "portkey-realtime-content-logging")?.granted ?? false;
  },
});

type Grouped<T extends string> = Record<string, number>;

function emptyGroup<T extends string>(names: readonly T[]): Grouped<T> {
  const result: Grouped<T> = {};
  for (const name of names) result[name] = 0;
  return result;
}

function countInto<T extends string>(group: Grouped<T>, value: string | undefined): void {
  const key = (value ?? "unknown") as T;
  group[key] = (group[key] ?? 0) + 1;
}

function sumOver(items: ReadonlyArray<Record<string, unknown>>, key: string): number {
  let total = 0;
  for (const item of items) {
    const value = item[key];
    if (typeof value === "number") total += value;
  }
  return total;
}

function groupByKind(
  items: ReadonlyArray<Record<string, unknown>>,
  kindKey: string,
  amountKey: string,
): { counts: Record<string, number>; microsUsd: Record<string, number> } {
  const counts: Record<string, number> = {};
  const microsUsd: Record<string, number> = {};
  for (const item of items) {
    const kind = typeof item[kindKey] === "string" ? (item[kindKey] as string) : "unknown";
    counts[kind] = (counts[kind] ?? 0) + 1;
    const amount = typeof item[amountKey] === "number" ? (item[amountKey] as number) : 0;
    microsUsd[kind] = (microsUsd[kind] ?? 0) + amount;
  }
  return { counts, microsUsd };
}

export const overview = queryGeneric({
  args: { serviceSecret: v.string(), windowMs: v.number() },
  handler: async (ctx, args) => {
    requireGatewaySecret(args.serviceSecret);
    const since = Math.max(0, now() - Math.max(1, Math.min(args.windowMs, 90 * 24 * 60 * 60 * 1000)));
    const [
      accounts,
      invites,
      subscriptions,
      walletEntries,
      inference,
      reservations,
      debts,
      events,
      refunds,
    ] = await Promise.all([
      ctx.db.query("didAccounts").collect(),
      ctx.db.query("invites").collect(),
      ctx.db.query("subscriptions").collect(),
      ctx.db.query("walletEntries").collect(),
      ctx.db.query("inferenceRequests").collect(),
      ctx.db.query("reservations").collect(),
      ctx.db.query("debts").collect(),
      ctx.db.query("creemEvents").collect(),
      ctx.db.query("refunds").collect(),
    ]);

    const recoveryStates = emptyGroup(["active", "pending", "locked"]);
    for (const row of accounts) countInto(recoveryStates, (row as any).recoveryState);

    const subscriptionStates = emptyGroup(["active", "trialing", "canceled", "past_due", "unpaid", "incomplete"]);
    for (const row of subscriptions) countInto(subscriptionStates, (row as any).status);

    const recentAccounts = accounts.filter((row) => (row as any).createdAt >= since);
    const recentEntries = walletEntries.filter((row) => (row as any).createdAt >= since);
    const recentInference = inference.filter((row) => (row as any).createdAt >= since);

    const inferenceStates = emptyGroup(["reserved", "running", "succeeded", "failed", "expired"]);
    for (const row of recentInference) countInto(inferenceStates, (row as any).state);

    const reconciliationReasons: Record<string, number> = {};
    for (const row of inference) {
      const reason = (row as any).reconciliationReason;
      if (typeof reason === "string") {
        reconciliationReasons[reason] = (reconciliationReasons[reason] ?? 0) + 1;
      }
    }

    const reservationStates = emptyGroup(["open", "settled", "released", "expired"]);
    for (const row of reservations) countInto(reservationStates, (row as any).state);

    const openDebts = debts.filter((row) => (row as any).state === "open");

    const eventStates = emptyGroup(["received", "applied", "ignored", "failed"]);
    for (const row of events) countInto(eventStates, (row as any).processingState);

