import { Hono } from "hono";
import { SignJWT, generateKeyPair, exportJWK, calculateJwkThumbprint } from "jose";
import { createDpopKeyPair, createDpopProofFactory } from "@notorganic/sdk";
import { TokenService } from "../apps/gateway/src/auth";
import { mountOrganizationRoutes } from "../apps/gateway/src/organization-routes";
import { openAIError } from "../apps/gateway/src/errors";
import { ACCESS_TOKEN_TYPE } from "@notorganic/contracts";
import { describe, expect, test } from "bun:test";
import { createHash } from "node:crypto";
import { createOrgSurfaceFixture, owner, member, billing, admin, outsider, secret, mutation, query } from "./org-surface-fixture";
const hash = (token: string) => createHash("sha256").update(token).digest("hex");
async function fixture(run: (f: Awaited<ReturnType<typeof createOrgSurfaceFixture>>) => Promise<void>) {
  const previous = process.env.CONVEX_GATEWAY_SECRET; process.env.CONVEX_GATEWAY_SECRET = secret;
  try { await run(await createOrgSurfaceFixture()); } finally { if (previous === undefined) delete process.env.CONVEX_GATEWAY_SECRET; else process.env.CONVEX_GATEWAY_SECRET = previous; }
}
describe("organization HTTP surface", () => {
  test("real JWT/DPoP middleware protects organization routes, checks scopes and rejects service tokens", () => fixture(async f => {
    const signing = await generateKeyPair("EdDSA", { extractable: true }), key = await createDpopKeyPair(), proof = createDpopProofFactory(key), time = Math.floor(Date.now() / 1000);
    (f.store as any).getAccount = async () => ({ account: { sessionVersion: 0 } }); (f.store as any).consumeDpopProof = async () => true;
    const tokens = new TokenService({ gatewayIssuer: "https://gateway.test", gatewayAudience: "notorganic", gatewaySigningPrivateJwk: await exportJWK(signing.privateKey), gatewaySigningPublicJwk: await exportJWK(signing.publicKey), store: f.store } as any), app = new Hono(); app.onError((error, c) => openAIError(c, error)); mountOrganizationRoutes(app, f.store, tokens);
    const token = async (token_type: "user" | "service", capabilities = ["orgs:read"]) => new SignJWT({ typ: ACCESS_TOKEN_TYPE, assertion_jti: "fixture-assertion", product: "frenzy", token_type, session_version: 0, capabilities, environment: "server", cnf: { jkt: await calculateJwkThumbprint(key.publicJwk) }, max_cost_microusd: 100 }).setProtectedHeader({ alg: "EdDSA" }).setIssuer("https://gateway.test").setAudience("notorganic").setSubject(owner).setIssuedAt(time).setExpirationTime(time + 300).setJti(crypto.randomUUID()).sign(signing.privateKey);
    const request = async (credential: string, withProof = true) => app.request("https://gateway.test/v1/organizations", { headers: { authorization: `DPoP ${credential}`, ...(withProof ? { dpop: await proof({ url: "https://gateway.test/v1/organizations", method: "GET", accessToken: credential }) } : {}) } });
    const user = await token("user"); expect((await request(user)).status).toBe(200); expect((await request(user, false)).status).toBe(401); expect((await request(await token("user", ["wallet:read"]))).status).toBe(403); expect((await request(await token("service"))).status).toBe(403);
  }));
  test("creation atomically creates owner, org billing account and wallet; list is membership-only", () => fixture(async f => {
    const created = await f.call("POST", "/v1/organizations", { name: "Another" }); expect(created.status).toBe(201); const body = await created.json() as any;
    expect(body.billingAccountId).toBeTruthy(); expect(await f.t.run(ctx => ctx.db.query("orgWallets").withIndex("by_account", q => q.eq("billingAccountId", body.billingAccountId)).unique())).toMatchObject({ balanceMicros: 0, reservedMicros: 0 });
    expect((await (await f.call("GET", "/v1/organizations")).json() as any).data).toHaveLength(2);
    f.as(outsider); expect((await (await f.call("GET", "/v1/organizations")).json() as any).data).toEqual([]);
    const denied = await f.call("GET", `/v1/organizations/${f.org.orgId}`); expect(denied.status).toBe(403);
  }));
  test("user token, context match and narrow scopes gate every route before mutation", () => fixture(async f => {
    f.as(owner, { tokenType: "service" }); expect((await f.call("POST", "/v1/organizations", { name: "Denied" })).status).toBe(403);
    f.as(owner, { orgId: "other" }); expect((await f.call("GET", `/v1/organizations/${f.org.orgId}`)).status).toBe(403);
    f.as(owner, { scopes: ["orgs:read"] }); expect((await f.call("PUT", `/v1/organizations/${f.org.orgId}/products/frenzy`)).status).toBe(403);
    expect((await f.call("GET", `/v1/organizations/${f.org.orgId}`)).status).toBe(200); expect(f.requestedScopes).toContain("products:manage");
  }));
  test("invitations return a random token once, persist only its hash and accept idempotently", () => fixture(async f => {
    const response = await f.call("POST", `/v1/organizations/${f.org.orgId}/invitations`, { role: "member", email: "fixture@example.test" }); expect(response.status).toBe(201); expect(response.headers.get("cache-control")).toBe("no-store");
    const invitation = await response.json() as any; expect(invitation.token).toMatch(/^noi_[A-Za-z0-9_-]{43}$/);
    const stored = await f.t.run(ctx => ctx.db.get(invitation.invitationId)); expect(stored).toMatchObject({ tokenHash: hash(invitation.token), emailHash: hash("fixture@example.test") }); expect(JSON.stringify(stored)).not.toContain(invitation.token); expect(JSON.stringify(stored)).not.toContain("fixture@example.test");
    f.as(outsider); const accepted = await f.call("POST", "/v1/org-invitations/accept", { token: invitation.token }); expect(accepted.status).toBe(200); expect(await (await f.call("POST", "/v1/org-invitations/accept", { token: invitation.token })).json()).toEqual(await accepted.json());
    f.as(member); expect((await f.call("POST", "/v1/org-invitations/accept", { token: invitation.token })).status).toBe(410);
  }));
  test("role, last-owner, disabled product, cap, access and seat removal have stable codes", () => fixture(async f => {
    const base = `/v1/organizations/${f.org.orgId}`, seat = `${base}/products/frenzy/seats/${f.memberIds[member]}`;
    const last = await f.call("DELETE", `${base}/members/${f.org.membershipId}`); expect(last.status).toBe(409); expect((await last.json() as any).error.code).toBe("last_owner");
    expect((await (await f.call("PUT", seat)).json() as any).error.code).toBe("product_disabled");
    expect((await f.call("PUT", `${base}/products/frenzy`)).status).toBe(200); await f.call("PUT", `${base}/products/frenzy/max-seats`, { maxSeats: 0 });
    expect((await (await f.call("PUT", seat)).json() as any).error.code).toBe("seat_cap_reached"); await f.call("DELETE", `${base}/products/frenzy/max-seats`); expect((await f.call("PUT", seat)).status).toBe(200);
    f.as(member); expect(await (await f.call("GET", `${base}/access?product=frenzy`)).json()).toMatchObject({ allowed: true }); expect((await f.call("GET", `${base}/members`)).status).toBe(403); expect((await (await f.call("GET", `${base}/seats`)).json() as any).data).toHaveLength(1);
    f.as(owner); await f.call("DELETE", `${base}/members/${f.memberIds[member]}`); f.as(member); expect(await (await f.call("GET", `${base}/access?product=frenzy`)).json()).toMatchObject({ allowed: false, code: "not_member" });
  }));
