import { expect, test } from "bun:test";
import { convexTest } from "convex-test";
import { makeFunctionReference } from "convex/server";
import schema from "../convex/schema";

const modules = {
  "../convex/_generated/server.js": () => import("../convex/_generated/server.js"),
  "../convex/gateway.ts": () => import("../convex/gateway"),
};

test("portal reports active product credits without making them spendable across products or accounts", async () => {
  const prior = process.env.CONVEX_GATEWAY_SECRET;
  process.env.CONVEX_GATEWAY_SECRET = "wallet-scopes-test";
  try {
    const t = convexTest(schema, modules);
    const did = "did:plc:wallet-scopes";
    const now = Date.now();
    await t.run(async (ctx) => {
      for (const [key, productScope, remainingMicros, expiresAt] of [
        ["twyne", "twyne", 7_000_000, now + 60_000],
        ["keating", "keating", 2_000_000, null],
        ["shared", null, 3_000_000, null],
        ["expired", "twyne", 5_000_000, now - 60_000],
      ] as const) {
        await ctx.db.insert("grantLots", {
          did, productScope, remainingMicros, expiresAt,
          source: "admin", sourceId: key, amountMicros: remainingMicros,
          createdAt: now,
        } as any);
      }
    });
    const ref = makeFunctionReference<"query">("gateway:wallet");
    const args = { serviceSecret: "wallet-scopes-test", did };
    const portal = await t.query(ref, { ...args, product: "notorganic" });
    expect(portal.scopedGrantMicros).toEqual({ twyne: 7_000_000, keating: 2_000_000 });
    expect(portal.availableGrantMicros).toBe(3_000_000);
    expect(portal.availableMicros).toBe(3_000_000);
    const twyne = await t.query(ref, { ...args, product: "twyne" });
    expect(twyne.availableGrantMicros).toBe(10_000_000);
    const other = await t.query(ref, { ...args, did: "did:plc:someone-else", product: "notorganic" });
    expect(other.scopedGrantMicros).toEqual({});
    expect(other.availableMicros).toBe(0);
  } finally {
    if (prior === undefined) delete process.env.CONVEX_GATEWAY_SECRET;
    else process.env.CONVEX_GATEWAY_SECRET = prior;
  }
});

