import { writeFileSync } from "node:fs";
import { createDpopFetch, issueNotOrganicAccessToken } from "/home/diogenes/Projects/apps/twyne/convex/lib/notorganic.ts";
const folder = "/home/diogenes/.cache/notorganic-runtime-release-20261023";
const issuer = "https://api.notorganic.info";
const did = "did:plc:h7t2qykaxwf6s7iez6pmhs45";
const child = Bun.spawn(["rtk", "proxy", "bunx", "convex", "env", "get", "--prod", "NOTORGANIC_ASSERTION_PRIVATE_KEY"], { cwd: "/home/diogenes/Projects/apps/twyne", stdout: "pipe", stderr: "pipe", env: Object.fromEntries(Object.entries(process.env).filter(([key]) => !key.startsWith("CONVEX_"))) });
const [key, _stderr, code] = await Promise.all([new Response(child.stdout).text(), new Response(child.stderr).text(), child.exited]);
if (code !== 0) throw new Error("Credential read failed; output redacted.");
const token = await issueNotOrganicAccessToken({ did, feature: "judgement", capabilities: ["wallet:read", "usage:read"], sessionVersion: 0 }, { NOTORGANIC_ENABLED: "true", NOTORGANIC_ISSUER: issuer, NOTORGANIC_AUDIENCE: "notorganic", NOTORGANIC_ASSERTION_PRIVATE_KEY: key.trim() });
const authenticated = createDpopFetch(token, fetch);
const headers = { "x-notorganic-product": "twyne", "x-notorganic-feature": "judgement" };
const walletResponse = await authenticated(`${issuer}/v1/wallet`, { headers, signal: AbortSignal.timeout(15_000) });
const wallet = await walletResponse.json() as any;
const usageResponse = await authenticated(`${issuer}/v1/usage?limit=100`, { headers, signal: AbortSignal.timeout(15_000) });
const usage = await usageResponse.json() as any;
const rows: any[] = usage.data ?? [];
const counts: Record<string, number> = {};
for (const row of rows) counts[row.state ?? "unknown"] = (counts[row.state ?? "unknown"] ?? 0) + 1;
const at = Date.now();
const report = {
  checkedAt: new Date(at).toISOString(), did, readOnly: true,
  wallet: { status: walletResponse.status, balanceMicros: wallet.balanceMicros, availableGrantMicros: wallet.availableGrantMicros, availableMicros: wallet.availableMicros, reservedMicros: wallet.reservedMicros, debtMicros: wallet.debtMicros, scopedGrantMicros: wallet.scopedGrantMicros },
  ledger: { status: usageResponse.status, rowsInspected: rows.length, mayBeTruncated: rows.length === 100, states: counts,
    activeRows: rows.filter(row => ["reserved", "running"].includes(row.state)).map(row => ({ requestId: row.requestId, model: row.model, feature: row.feature, state: row.state, createdAt: row.createdAt, updatedAt: row.updatedAt, ageSeconds: Math.round((at - row.createdAt) / 1000) })),
    reconciliationRows: rows.filter(row => row.reconciliationReason).map(row => ({ requestId: row.requestId, state: row.state, billedMicros: row.billedMicros, reconciliationReason: row.reconciliationReason })),
  },
};
writeFileSync(`${folder}/reservation-audit-${at}.json`, JSON.stringify(report, null, 2) + "\n", { mode: 0o600 });
writeFileSync(`${folder}/reservation-audit-latest.json`, JSON.stringify(report, null, 2) + "\n", { mode: 0o600 });
console.log(JSON.stringify(report, null, 2));

