export const sweepReservations = internalMutationGeneric({
  args: {},
  handler: async (ctx) => {
    const candidates = await ctx.db
      .query("reservations")
      .withIndex("by_state_expiry", (q) => q.eq("state", "open"))
      .take(100);
    const expired = candidates.filter(
      (reservation) => reservation.expiresAt <= now(),
    );
    for (const reservation of expired) {
      const inference = await ctx.db
        .query("inferenceRequests")
        .withIndex("by_request", (q) =>
          q.eq("requestId", reservation.requestId),
        )
        .unique();
      if (inference && ["vid", "tavus"].includes(inference.feature) && inference.state === "running") {
        const job = await ctx.db.query("asyncMediaJobs").withIndex("by_job", q => q.eq("jobId", inference.requestId)).unique();
        if (job && !job.terminal) {
          // Queue completion can outlive the initial lease or a gateway restart.
          // The durable poller owns resolution; keep its original maximum held.
          await ctx.db.patch(reservation._id, { expiresAt: now() + 30 * 60_000 });
          continue;
        }
        if (reservation.orgId) await settleOrgFunds(ctx, reservation, reservation.estimatedMicros);
        else await settleFunds(ctx, reservation, reservation.estimatedMicros);
        await ctx.db.patch(inference._id, { state: "succeeded", billedMicros: reservation.estimatedMicros, reconciliationReason: "async_worker_lost_before_job_persisted", updatedAt: now(), completedAt: now() });
        continue;
      }
      // A crashed Live relay may already have incurred voice duration. Do not
      // turn missing final usage into free inference. Keep the estimate explicit.
      if (inference?.feature === "live" && inference.state === "running") {
        if (reservation.orgId) await settleOrgFunds(ctx, reservation, reservation.estimatedMicros);
        else await settleFunds(ctx, reservation, reservation.estimatedMicros);
        await ctx.db.patch(inference._id, {
          state: "succeeded",
          billedMicros: reservation.estimatedMicros,
          reconciliationReason: "live_worker_lost_final_usage_unconfirmed",
          updatedAt: now(),
          completedAt: now(),
        });
        continue;
      }
      if (reservation.orgId) await settleOrgFunds(ctx, reservation, 0, "expired");
      else await releaseFunds(ctx, reservation, "expired");
      if (
        inference &&
        (inference.state === "reserved" || inference.state === "running")
      ) {
        await ctx.db.patch(inference._id, {
          state: "expired",
          errorCode: "RESERVATION_EXPIRED",
          updatedAt: now(),
          completedAt: now(),
        });
      }
    }
    if (expired.length === 100) await ctx.scheduler.runAfter(0, sweepRef, {});
    return expired.length;
  },
});

import { cronJobs, makeFunctionReference } from "convex/server";

const crons = cronJobs();
crons.interval("purge expired agent credentials and registration limits", { minutes: 5 }, makeFunctionReference<"mutation">("agentAuth:purgeExpired"), {});
crons.interval("sweep stale inference reservations", { minutes: 5 }, makeFunctionReference<"mutation">("maintenance:sweepReservations"), {});
crons.interval("purge expired encrypted responses", { hours: 1 }, makeFunctionReference<"mutation">("maintenance:purgeResponses"), {});
crons.interval("purge expired DPoP replay records", { minutes: 5 }, makeFunctionReference<"mutation">("maintenance:purgeDpopProofs"), {});
crons.interval("purge expired portal sessions and OAuth state", { minutes: 15 }, makeFunctionReference<"mutation">("portalSessions:purgeExpired"), {});
crons.interval("purge expired passkey challenges", { minutes: 15 }, makeFunctionReference<"mutation">("passkeys:purgeExpired"), {});
crons.interval("purge expired public-client authorization state", { minutes: 5 }, makeFunctionReference<"mutation">("publicClientAuth:purgeExpired"), {});
crons.interval("keep first-party applications registered", { hours: 24 }, makeFunctionReference<"mutation">("publicProfiles:registerFirstPartyApplications"), {});
crons.cron("issue monthly subscription grants", "17 3 1 * *", makeFunctionReference<"mutation">("maintenance:grantSubscriptions"), {
  cursor: null,
});

// Daily catch-up discovers missed closed UTC months. Disabled until seat prices
// and provider collection are approved through ORG_SEAT_COLLECTION_ENABLED.
crons.cron("invoice closed organization seat months", "43 3 * * *", makeFunctionReference<"action">("orgPayments:monthlyInvoices"), {});

crons.interval("poll organization directory events", { minutes: 1 }, makeFunctionReference<"action">("orgDirectories:poll"), {});
crons.interval("reconcile organization directories", { hours: 6 }, makeFunctionReference<"action">("orgDirectories:poll"), { reconcile: true });
crons.interval("purge organization SSO flows", { minutes: 15 }, makeFunctionReference<"mutation">("orgSso:purgeFlows"), {});

crons.interval("backfill explicit sandbox and execution-config ownership", { hours: 24 }, makeFunctionReference<"mutation">("maintenance:migrateResourceOwnership"), {});

export default crons;

