import { enqueueFinance, financeAuthority, requireSourceWallet, requireFinancialOwner } from "./unisonFinance";
import { mutationGeneric, queryGeneric } from "convex/server";
import { ConvexError, v } from "convex/values";
import { assertMicros, audit, now, requireDid, requireServiceScope, walletForUpdate } from "./lib";

export async function reserveFunds(
  ctx: any,
  args: { requestId: string; did: string; product: string; estimatedMicros: number; ttlMs: number },
): Promise<any> {
  await requireFinancialOwner(ctx, args.did);
  await requireSourceWallet(ctx, args.did);
  assertMicros(args.estimatedMicros, "estimatedMicros");
  if (args.ttlMs < 30_000 || args.ttlMs > 30 * 60_000) throw new Error("INVALID_TTL");
  const wallet = await walletForUpdate(ctx, args.did);
  if (wallet.debtMicros > 0) throw new ConvexError("HOSTED_INFERENCE_BLOCKED_BY_DEBT");
  const existing = await ctx.db.query("reservations").withIndex("by_request", (q: any) => q.eq("requestId", args.requestId)).unique();
  if (existing) {
    if (existing.orgId !== undefined || existing.did !== args.did || existing.product !== args.product || existing.estimatedMicros !== args.estimatedMicros) {
      throw new Error("IDEMPOTENCY_CONFLICT");
    }
    return existing;
  }

  let remaining = args.estimatedMicros;
  const grantAllocations: Array<{ lotId: any; amountMicros: number }> = [];
  const lots = await ctx.db
    .query("grantLots")
    .withIndex("by_did_expiry", (q: any) => q.eq("did", args.did))
    .take(256);
  const activeLots = lots.filter(
    (lot: any) =>
      (lot.expiresAt === null || lot.expiresAt > now()) &&
      (lot.productScope === null || lot.productScope === args.product),
  );
  activeLots.sort(
    (a: any, b: any) =>
      (a.expiresAt ?? Number.MAX_SAFE_INTEGER) -
        (b.expiresAt ?? Number.MAX_SAFE_INTEGER) ||
      a.issuedAt - b.issuedAt,
  );
  for (const lot of activeLots) {
    if (remaining === 0) break;
    const amountMicros = Math.min(remaining, lot.remainingMicros);
    if (amountMicros === 0) continue;
    await ctx.db.patch(lot._id, { remainingMicros: lot.remainingMicros - amountMicros });
    grantAllocations.push({ lotId: lot._id, amountMicros });
    remaining -= amountMicros;
  }

  const availableCash = wallet.balanceMicros - wallet.reservedMicros;
  if (availableCash < remaining) {
    for (const allocation of grantAllocations) {
      const lot = await ctx.db.get(allocation.lotId);
      if (lot) await ctx.db.patch(lot._id, { remainingMicros: lot.remainingMicros + allocation.amountMicros });
    }
    throw new ConvexError("INSUFFICIENT_FUNDS");
  }
  await ctx.db.patch(wallet._id, { reservedMicros: wallet.reservedMicros + remaining, updatedAt: now() });
  const reservationId = await ctx.db.insert("reservations", {
    requestId: args.requestId,
    did: args.did,
    product: args.product,
    estimatedMicros: args.estimatedMicros,
    grantMicros: args.estimatedMicros - remaining,
    cashMicros: remaining,
    grantAllocations,
    state: "open",
    expiresAt: now() + args.ttlMs,
    createdAt: now(),
  });
  return await ctx.db.get(reservationId);
}

export async function settleFunds(ctx: any, reservation: any, actualMicros: number): Promise<void> {
  assertMicros(actualMicros, "actualMicros");
  if (reservation.state !== "open") return;
  await requireSourceWallet(ctx, reservation.did);
  const wallet = await walletForUpdate(ctx, reservation.did);
  const consumedGrant = Math.min(actualMicros, reservation.grantMicros);
  let grantToReturn = reservation.grantMicros - consumedGrant;

