import { queryGeneric } from "convex/server";
import { v } from "convex/values";
import { requireGatewaySecret, requirePortalSecret } from "./lib";
import { isAccountDeleted } from "./achievements";

/** Read-only identity bridge while OAuth/account lifecycle remains on Convex.
 * Never exports OAuth tokens, email, signing keys or a caller-controlled status. */
async function snapshot(ctx: any, did: string) {
  const [account, deleted, mappings] = await Promise.all([
    ctx.db.query("didAccounts").withIndex("by_did", (q: any) => q.eq("did", did)).unique(),
    isAccountDeleted(ctx, did),
    ctx.db.query("productMappings").withIndex("by_did_product", (q: any) => q.eq("did", did)).take(101),
  ]);
  if (mappings.length > 100) throw new Error("ACCOUNT_MAPPING_CAPACITY");
  return {
    owner: did,
    active: !deleted && (!account || account.recoveryState === "active"),
    deleted,
    memberships: mappings.map((row: any) => ({ product: row.product, active: row.status === "active", createdAt: row.createdAt })),
  };
}

export const gatewaySnapshot = queryGeneric({
  args: { serviceSecret: v.string(), did: v.string() },
  handler: async (ctx, args) => { requireGatewaySecret(args.serviceSecret); return snapshot(ctx, args.did); },
});
export const portalSnapshot = queryGeneric({
  args: { serviceSecret: v.string(), did: v.string() },
  handler: async (ctx, args) => { requirePortalSecret(args.serviceSecret); return snapshot(ctx, args.did); },
});

