/** Fixture-only, loopback-only money migration. No ConvexHttpClient or deployment RPC. */
import { z } from "zod";
import { canonical, financeDigest } from "../convex/unisonFinance";
const integer = z.number().int().nonnegative().safe();
const receipt = z.object({ id: z.string().min(1).max(1024), digest: z.string().regex(/^[a-f0-9]{64}$/), payload: z.string().max(1048576) }).strict();
const envelope = z.object({ version: z.literal(1), fixtureOnly: z.literal(true), owner: z.string().startsWith("did:example:"), asOf: integer, snapshot: receipt, archive: receipt }).strict();
export type MoneyExport = z.infer<typeof envelope>;
const tables = ["wallets", "grantLots", "debts", "walletEntries", "refunds", "subscriptions", "paddleTransactions", "paddleAdjustments", "creemEvents"] as const;
function check(condition: unknown, message: string): asserts condition { if (!condition) throw new Error(message); }
const micros = (n: unknown): number => integer.parse(n);
const total = (values: number[]) => values.reduce((a, b) => micros(a + b), 0);
export function moneyEventIds(records: Record<string, any[]>): string[] {
  return [...new Set([
    ...records.creemEvents!.flatMap(row => [row.eventId, `paddle-event:${row.eventId}`]),
    ...records.paddleAdjustments!.map(row => `paddle-refund:${row.adjustmentId}`),
    ...records.walletEntries!.map(row => `credit:${row.idempotencyKey}`),
    ...records.grantLots!.map(row => `grant:${row.idempotencyKey}`),
  ])].sort();
}
/** Derive financial state independently from the receipt snapshot. */
export function sourceMoneySnapshot(owner: string, id: string, records: Record<string, any[]>) {
  check(records.wallets!.length <= 1, "MONEY_MULTIPLE_WALLETS");
  const wallet = records.wallets![0];
