import { canonical, financeAuthority, financeDigest } from "./unisonFinance";

/** Independent from gateway storage selection. Never removes an existing fence. */
export async function requirePaymentAuthority(ctx: any, did?: string): Promise<void> {
  const selected = process.env.NOTORGANIC_PAYMENT_BACKEND ?? "convex";
  if (!["convex", "unison", "freeze"].includes(selected)) throw new Error("PAYMENT_CUTOVER_INVALID_SELECTION");
  if (selected === "freeze") throw new Error("PAYMENT_CUTOVER_FROZEN");
  if (selected === "unison" && (!did || !await financeAuthority(ctx, did))) {
    throw new Error("PAYMENT_CUTOVER_OWNER_NOT_FENCED");
  }
  // In convex mode an already fenced owner STILL queues to native. Flipping an
  // environment variable cannot make stale source balances spendable again.
}

/** Local fixture exporter. No RPC registration or deployment client. Run only
 * after prepare has fenced the owner and the webhook/consumer freeze is active.
 * Financial fields and IDs are retained; Convex's fractional _creationTime is
 * platform metadata, not a monetary timestamp, and is omitted. */
export async function captureMoneyExport(ctx: any, did: string, asOf: number): Promise<any> {
  if (!did.startsWith("did:example:") || !Number.isSafeInteger(asOf) || asOf < 0) throw new Error("PAYMENT_CUTOVER_FIXTURE_REQUIRED");
  if (process.env.NOTORGANIC_PAYMENT_BACKEND !== "freeze") throw new Error("PAYMENT_CUTOVER_FREEZE_REQUIRED");
  const authority = await financeAuthority(ctx, did);
  if (!authority || authority.nextSequence !== 0) throw new Error("PAYMENT_CUTOVER_PRISTINE_FENCE_REQUIRED");
  const bounded = async (query: any) => {
    const rows = await query.take(10001);
    if (rows.length > 10000) throw new Error("PAYMENT_CUTOVER_EXPORT_CAPACITY");
    return rows.map(({ _creationTime: _, ...row }: any) => row);
  };
  const owned = (table: string, index: string) => bounded(ctx.db.query(table).withIndex(index, (q: any) => q.eq("did", did)));
  const records: Record<string, any[]> = {
    wallets: await owned("wallets", "by_did"),
    grantLots: await owned("grantLots", "by_did_expiry"),
    debts: await owned("debts", "by_did_state"),
    walletEntries: await owned("walletEntries", "by_did_created"),
    refunds: await owned("refunds", "by_erasure_owner"),
    subscriptions: await owned("subscriptions", "by_did"),
    paddleTransactions: await owned("paddleTransactions", "by_erasure_owner"),
    paddleAdjustments: [], creemEvents: [],
  };
  for (const transaction of records.paddleTransactions!) {
    records.paddleAdjustments!.push(...await bounded(ctx.db.query("paddleAdjustments").withIndex("by_transaction_id", (q: any) => q.eq("transactionId", transaction.transactionId))));
  }
  const objectIds = new Set<string>([
    ...records.paddleTransactions!.map(row => row.transactionId),
    ...records.paddleAdjustments!.map(row => row.adjustmentId),
    ...records.subscriptions!.map(row => row.creemSubscriptionId).filter(Boolean),
    ...records.refunds!.flatMap(row => [row.refundId, row.paymentReference]),
    ...records.grantLots!.filter(row => row.idempotencyKey.startsWith("creem-purchase:")).map(row => row.idempotencyKey.slice(15)),
  ]);
  for (const id of objectIds) records.creemEvents!.push(...await bounded(ctx.db.query("creemEvents").withIndex("by_object_created", (q: any) => q.eq("objectId", id))));
  for (const [table, rows] of Object.entries(records)) records[table] = [...new Map(rows.map(row => [String(row._id), row])).values()].sort((a, b) => String(a._id).localeCompare(String(b._id)));
  const eventIds = [...new Set([
    ...records.creemEvents!.flatMap(row => [row.eventId, `paddle-event:${row.eventId}`]),
    ...records.paddleAdjustments!.map(row => `paddle-refund:${row.adjustmentId}`),
    ...records.walletEntries!.map(row => `credit:${row.idempotencyKey}`),
    ...records.grantLots!.map(row => `grant:${row.idempotencyKey}`),
  ])].sort();
  const payload = canonical({ owner: did, eventIds, records });
  const archive = { id: `source-receipts:${authority.migrationId}`, payload, digest: await financeDigest(payload) };
  return { version: 1, fixtureOnly: true, owner: did, asOf, snapshot: { id: authority.migrationId, payload: authority.snapshotJson, digest: authority.snapshotDigest }, archive };
}

/** Fixture-only source approval, after a native transactional retirement receipt.
 * No RPC is registered. Must run in the same local source transaction as its
 * reconciliation and fence removal. A flag change alone never removes fences. */
export async function approveMoneyRevert(ctx: any, original: any, approval: any): Promise<void> {
  if (process.env.NOTORGANIC_PAYMENT_BACKEND !== "freeze") throw new Error("PAYMENT_CUTOVER_FREEZE_REQUIRED");
  if (!original.fixtureOnly || original.version !== 1 || !original.owner?.startsWith("did:example:")) throw new Error("PAYMENT_CUTOVER_FIXTURE_REQUIRED");
  if (approval.owner !== original.owner || approval.id !== original.snapshot.id || approval.digest !== original.snapshot.digest || approval.archiveDigest !== original.archive.digest || approval.state !== "reverted" || approval.sequence !== 0 || approval.requestCount !== 0) throw new Error("PAYMENT_CUTOVER_REVERT_APPROVAL_INVALID");
  const row = await financeAuthority(ctx, original.owner);
  if (!row) return; // Native retirement receipt makes this repeatable.
  if (row.nextSequence !== 0 || row.snapshotDigest !== approval.digest || row.migrationId !== approval.id) throw new Error("PAYMENT_CUTOVER_NATIVE_ACTIVITY");
  const pending = await ctx.db.query("unisonFinanceOutbox").withIndex("by_owner_sequence", (q: any) => q.eq("did", original.owner)).take(1);
  if (pending.length) throw new Error("PAYMENT_CUTOVER_NATIVE_ACTIVITY");
  const current = await captureMoneyExport(ctx, original.owner, original.asOf);
  if (canonical(current) !== canonical(original)) throw new Error("PAYMENT_CUTOVER_SOURCE_RECONCILIATION_FAILED");
  await ctx.db.delete(row._id);
}

