/** Independent WebCrypto verification of the compiled native Unison auth utilities. */
import { test } from "bun:test";
import assert from "node:assert/strict";
import { resolve } from "node:path";

const compiled = resolve(process.env.NOTORGANIC_AUTH_TEST_COMPILED ?? resolve(import.meta.dir, "../../.local/unison-sdk/auth-wire-tests.uc"));
const runtime = process.env.UNISON_RUNTIME ?? resolve(import.meta.dir, "../../.local/unison/toolchain/unison/unison");
const base64 = (bytes: BufferSource) => Buffer.from(bytes instanceof ArrayBuffer ? new Uint8Array(bytes) : new Uint8Array(bytes.buffer, bytes.byteOffset, bytes.byteLength)).toString("base64url");
const decode = (text: string) => new Uint8Array(Buffer.from(text, "base64url"));
async function native(request: Record<string, unknown>): Promise<any> {
  const child = Bun.spawn([runtime, "run.compiled", compiled], { stdin: "pipe", stdout: "pipe", stderr: "pipe" });
  // Secrets travel through a private pipe, never argv, environment or logs.
  child.stdin.write(JSON.stringify(request) + "\n"); child.stdin.end();
  const [raw, stderr, code] = await Promise.all([new Response(child.stdout).text(), new Response(child.stderr).text(), child.exited]);
  assert(code === 0, `Native auth fixture exited ${code}: ${stderr}`);
  return JSON.parse(raw);
}
async function key(): Promise<{ privateKey: string; publicJwk: JsonWebKey }> {
  const result = await native({ operation: "keys" }); assert(result.ok === true, "Native key generation failed"); return result.data;
}
async function proof(privateKey: string, options: Record<string, unknown> = {}): Promise<string> {
  const result = await native({ operation: "proof", privateKey, seconds: 1791580800, method: "POST", htu: "https://api.example.com/v1/judgement", token: "disposable-public-test-token", nonce: "fixture.nonce", ...options });
  assert(result.ok === true, "Native proof generation failed"); return result.data.proof;
}
async function verify(jwt: string, jwk: JsonWebKey): Promise<{ header: any; claims: any }> {
  const parts = jwt.split("."); assert(parts.length === 3, "JWT must have exactly three parts");
  const [headerPart, claimsPart, signaturePart] = parts as [string, string, string];
  const header = JSON.parse(Buffer.from(headerPart, "base64url").toString());
  const claims = JSON.parse(Buffer.from(claimsPart, "base64url").toString());
  const signature = decode(signaturePart); assert(signature.byteLength === 64, "Signature must be JOSE r||s, not ASN.1 DER");
  const publicKey = await crypto.subtle.importKey("jwk", jwk, { name: "ECDSA", namedCurve: "P-256" }, false, ["verify"]);
  assert(await crypto.subtle.verify({ name: "ECDSA", hash: "SHA-256" }, publicKey, signature, new TextEncoder().encode(`${headerPart}.${claimsPart}`)), "Native signature failed independent WebCrypto verification");
  assert(!await crypto.subtle.verify({ name: "ECDSA", hash: "SHA-256" }, publicKey, signature, new TextEncoder().encode(`${headerPart}.${claimsPart}altered`)), "Altered JWT message was accepted");
  return { header, claims };
}

test("native PKCE has fresh secure verifiers and WebCrypto-equivalent S256 challenges", async () => {
  const first = await native({ operation: "pkce" }); const second = await native({ operation: "pkce" });
  assert(first.ok && second.ok, "Native PKCE failed");
  assert(/^[A-Za-z0-9_-]{43}$/.test(first.data.verifier), "Verifier must encode 32 secure bytes");
  assert(first.data.verifier !== second.data.verifier, "PKCE verifier reused");
  const challenge = base64(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(first.data.verifier)));
  assert(challenge === first.data.challenge, "PKCE challenge differs from independent WebCrypto SHA-256");
}, 15_000);

test("native ES256 proofs verify independently and bind fresh IDs, token, nonce and target", async () => {
  const generated = await key(); const other = await key();
  assert(generated.privateKey.length === 43 && decode(generated.privateKey).byteLength === 32, "Wrong serialized private-key format");
  assert(generated.privateKey !== other.privateKey, "Key generator reused private scalar");
  const jwt = await proof(generated.privateKey); const second = await proof(generated.privateKey);
  const { header, claims } = await verify(jwt, generated.publicJwk);
  const next = await verify(second, generated.publicJwk);
  assert(header.typ === "dpop+jwt" && header.alg === "ES256", "Invalid DPoP JOSE header");
  assert(header.jwk.kty === "EC" && header.jwk.crv === "P-256" && !Object.hasOwn(header.jwk, "d"), "Header must contain only public key data");
  assert(header.jwk.x === generated.publicJwk.x && header.jwk.y === generated.publicJwk.y, "Proof key differs from generated public key");
  assert(claims.htm === "POST" && claims.htu === "https://api.example.com/v1/judgement" && claims.iat === 1791580800, "Method/target/issued-at binding mismatch");
  assert(/^[A-Za-z0-9_-]{22}$/.test(claims.jti) && claims.jti !== next.claims.jti, "DPoP jti lacks fresh 128-bit entropy");
  assert(claims.nonce === "fixture.nonce", "Server nonce missing");
  assert(claims.ath === base64(await crypto.subtle.digest("SHA-256", new TextEncoder().encode("disposable-public-test-token"))), "Access-token SHA-256 hash differs from WebCrypto");
  const tokenProof = await proof(generated.privateKey, { htu: "http://127.0.0.1:8893/oauth/token", token: null, nonce: null });
  const tokenClaims = (await verify(tokenProof, generated.publicJwk)).claims;
  assert(!Object.hasOwn(tokenClaims, "ath") && !Object.hasOwn(tokenClaims, "nonce"), "Token endpoint invented an access-token hash or nonce");
}, 20_000);

test("legacy private JWK import preserves token-bound key and rejects mismatched public points", async () => {
  const pair = await crypto.subtle.generateKey({ name: "ECDSA", namedCurve: "P-256" }, true, ["sign", "verify"]);
  const privateJwk = await crypto.subtle.exportKey("jwk", pair.privateKey);
  const publicJwk = await crypto.subtle.exportKey("jwk", pair.publicKey);
  const imported = await native({ operation: "importJwk", jwk: privateJwk });
  assert(imported.ok === true, "Valid existing private JWK rejected");
  assert(imported.data.privateKey === privateJwk.d, "Import changed the token-bound private scalar");
  assert(imported.data.publicJwk.x === publicJwk.x && imported.data.publicJwk.y === publicJwk.y, "Import changed token-bound public coordinates");
  await verify(await proof(imported.data.privateKey), publicJwk);
  const mismatched = await native({ operation: "importJwk", jwk: { ...privateJwk, x: "wrong-public-point" } });
  assert(mismatched.ok === false, "Mismatched JWK public point accepted");
}, 15_000);

test("native proof rejects malformed key, wrong method, ambiguous URL and invalid nonce", async () => {
  const generated = await key();
  for (const invalid of [{ privateKey: "not-a-key" }, { method: "get" }, { htu: "https://api.example.com/v1/account?query=1" }, { htu: "https://api.example.com/v1/account#fragment" }, { htu: "http://remote.example/v1/account" }, { nonce: "invalid\nnonce" }, { token: "invalid\rtoken" }, { seconds: 0 }]) {
    const result = await native({ operation: "proof", privateKey: generated.privateKey, seconds: 1791580800, method: "GET", htu: "https://api.example.com/v1/account", token: "fixture-token", ...invalid });
    assert(result.ok === false, "Invalid proof input was accepted");
  }
}, 30_000);

