import type { JudgementAnswer, JudgementQuestion } from '@notorganic/contracts';
import { GatewayError } from '../errors';
export function invalidDecisionResponse(): never {
  throw new GatewayError(502, 'api_error', 'The decision provider returned invalid answers.', 'judgement_invalid_response');
}
export function record(value: unknown): value is Record<string, unknown> { return !!value && typeof value === 'object' && !Array.isArray(value); }
function probability(value: unknown): value is number { return typeof value === 'number' && Number.isFinite(value) && value >= 0 && value <= 1; }
function exactKeys(value: Record<string, unknown>, keys: string[]): boolean { return Object.keys(value).length === keys.length && keys.every(key => Object.hasOwn(value, key)); }
export const roundingTolerance = (entries: number) => entries * 0.0000005 + Number.EPSILON * entries;
export function validateDecisionAnswers(questions: Record<string, JudgementQuestion>, raw: unknown): Record<string, JudgementAnswer> {
  if (!record(raw) || !exactKeys(raw, Object.keys(questions))) invalidDecisionResponse();
  for (const [name, q] of Object.entries(questions)) {
    const a = raw[name];
    if (!record(a) || a.type !== q.type) invalidDecisionResponse();
    if (q.type === 'noul') {
      if (!exactKeys(a, ['type', 'noul']) || !probability(a.noul)) invalidDecisionResponse();
      continue;
    }
    if (!probability(a.confidence) || !record(a.probabilities)) invalidDecisionResponse();
    const keys = q.type === 'choice' ? Object.keys(q.criteria) : q.criteria.map((_, i) => String(i));
    if (!exactKeys(a.probabilities, keys) || !Object.values(a.probabilities).every(probability)) invalidDecisionResponse();
    const probabilities = a.probabilities as Record<string, number>;
    if (Math.abs(Object.values(probabilities).reduce((x, y) => x + y, 0) - 1) > roundingTolerance(keys.length)) invalidDecisionResponse();
    if (q.type === 'choice') {
      if (typeof a.choice !== 'string' || !Object.hasOwn(probabilities, a.choice) || Object.values(probabilities).some(p => p > probabilities[a.choice as string]!)) invalidDecisionResponse();
    } else {
      if (!record(a.legend) || !exactKeys(a.legend, keys) || keys.some((key, i) => (a.legend as Record<string, unknown>)[key] !== q.criteria[i]) || typeof a.score !== 'number' || !Number.isFinite(a.score) || a.score < 0 || a.score > keys.length - 1) invalidDecisionResponse();
      const mean = keys.reduce((sum, key) => sum + Number(key) * probabilities[key]!, 0);
      if (Math.abs(a.score - mean) > roundingTolerance(keys.length * keys.length)) invalidDecisionResponse();
    }
  }
  return raw as Record<string, JudgementAnswer>;
}

