const did = "did:plc:h7t2qykaxwf6s7iez6pmhs45";
async function query(path: string, args: Record<string, unknown>) {
  const response = await fetch(`${variables.CONVEX_URL}/api/query`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ path, args: { serviceSecret: variables.CONVEX_GATEWAY_SECRET, did, ...args }, format: "json" }), signal: AbortSignal.timeout(20_000) });
  const body = await response.json() as any;
  if (!response.ok || body.status !== "success") throw new Error(`Read-only query failed (${response.status}); details redacted.`);
  return body.value;
}
