export const sweepReservations = internalMutationGeneric({
  args: {},
  handler: async (ctx) => {
    const candidates = await ctx.db
      .query("reservations")
      .withIndex("by_state_expiry", (q) => q.eq("state", "open"))
      .take(100);
    const expired = candidates.filter(
      (reservation) => reservation.expiresAt <= now(),
    );
    for (const reservation of expired) {
      const inference = await ctx.db
        .query("inferenceRequests")
        .withIndex("by_request", (q) =>
          q.eq("requestId", reservation.requestId),
        )
        .unique();
      if (inference && ["vid", "tavus"].includes(inference.feature) && inference.state === "running") {
        const job = await ctx.db.query("asyncMediaJobs").withIndex("by_job", q => q.eq("jobId", inference.requestId)).unique();
        if (job && !job.terminal) {
          // Queue completion can outlive the initial lease or a gateway restart.
          // The durable poller owns resolution; keep its original maximum held.
          await ctx.db.patch(reservation._id, { expiresAt: now() + 30 * 60_000 });
          continue;
        }
        if (reservation.orgId) await settleOrgFunds(ctx, reservation, reservation.estimatedMicros);
        else await settleFunds(ctx, reservation, reservation.estimatedMicros);
        await ctx.db.patch(inference._id, { state: "succeeded", billedMicros: reservation.estimatedMicros, reconciliationReason: "async_worker_lost_before_job_persisted", updatedAt: now(), completedAt: now() });
        continue;
      }
      // A crashed Live relay may already have incurred voice duration. Do not
      // turn missing final usage into free inference. Keep the estimate explicit.
      if (inference?.feature === "live" && inference.state === "running") {
        if (reservation.orgId) await settleOrgFunds(ctx, reservation, reservation.estimatedMicros);
        else await settleFunds(ctx, reservation, reservation.estimatedMicros);
        await ctx.db.patch(inference._id, {
          state: "succeeded",
          billedMicros: reservation.estimatedMicros,
          reconciliationReason: "live_worker_lost_final_usage_unconfirmed",
          updatedAt: now(),
          completedAt: now(),
        });
        continue;
      }
      if (reservation.orgId) await settleOrgFunds(ctx, reservation, 0, "expired");
      else await releaseFunds(ctx, reservation, "expired");
      if (
        inference &&
        (inference.state === "reserved" || inference.state === "running")
      ) {
        await ctx.db.patch(inference._id, {
          state: "expired",
          errorCode: "RESERVATION_EXPIRED",
          updatedAt: now(),
          completedAt: now(),
        });
      }
    }
    if (expired.length === 100) await ctx.scheduler.runAfter(0, sweepRef, {});
    return expired.length;
  },
});

export const purgeResponses = internalMutationGeneric({
  args: {},
  handler: async (ctx) => {
    const batch = await ctx.db
      .query("encryptedResponses")
      .withIndex("by_expiry")
      .take(100);
    const expired = batch.filter((response) => response.expiresAt <= now());
    for (const response of expired) await ctx.db.delete(response._id);
    if (expired.length === 100) await ctx.scheduler.runAfter(0, purgeRef, {});
    return expired.length;
  },
});

