export interface TransitCiphertext {
  ciphertext: string;
  keyVersion: string;
  aadHash: string;
}

export interface OpenBaoTransitConfig {
  address: string;
  token?: string;
  roleId?: string;
  secretId?: string;
  keyName?: string;
  fetch?: typeof fetch;
}

function base64(value: string): string {
  return Buffer.from(value, "utf8").toString("base64");
}

async function sha256(value: string): Promise<string> {
  const digest = await crypto.subtle.digest(
    "SHA-256",
    new TextEncoder().encode(value),
  );
  return Buffer.from(new Uint8Array(digest)).toString("base64url");
}

export class OpenBaoTransit {
  private readonly request: typeof fetch;
  private readonly baseUrl: string;
  private readonly keyName: string;
  private token?: string;
  private tokenExpiresAt = 0;

  constructor(private readonly config: OpenBaoTransitConfig) {
    this.request = config.fetch ?? globalThis.fetch.bind(globalThis);
    this.baseUrl = config.address.replace(/\/$/, "");
    this.keyName = config.keyName ?? "provider-responses";
    this.token = config.token;
    if (!this.token && (!config.roleId || !config.secretId)) {
      throw new Error("OpenBao requires a token or AppRole credentials");
    }
  }

  async encrypt(plaintext: string, context: string): Promise<TransitCiphertext> {
    const response = await this.call("encrypt", {
      plaintext: base64(plaintext),
      context: base64(context),
    });
    const ciphertext = response.ciphertext;
    if (typeof ciphertext !== "string") {
      throw new Error("OpenBao transit did not return ciphertext");
    }
    const keyVersion =
      typeof response.key_version === "number"
        ? String(response.key_version)
        : ciphertext.split(":")[1] ?? "unknown";
    return { ciphertext, keyVersion, aadHash: await sha256(context) };
  }

  async decrypt(ciphertext: string, context: string): Promise<string> {
    const response = await this.call("decrypt", {
      ciphertext,
      context: base64(context),
    });
    if (typeof response.plaintext !== "string") {
      throw new Error("OpenBao transit did not return plaintext");
    }
    return Buffer.from(response.plaintext, "base64").toString("utf8");
  }

  async healthCheck(): Promise<void> {
    const response = await this.request(
      `${this.baseUrl}/v1/sys/health?standbyok=true`,
    );
    if (!response.ok) {
      throw new Error(`OpenBao health check failed (${response.status})`);
    }
  }

  private async call(
    operation: "encrypt" | "decrypt",
    body: Record<string, string>,
  ): Promise<Record<string, unknown>> {
    const token = await this.accessToken();
    const response = await this.request(
      `${this.baseUrl}/v1/transit/${operation}/${encodeURIComponent(this.keyName)}`,
      {
        method: "POST",
        headers: {
          "content-type": "application/json",
          "x-vault-token": token,
        },
        body: JSON.stringify(body),
      },
    );
    if (!response.ok) {
      throw new Error(
        `OpenBao transit ${operation} failed (${response.status}): ${(await response.text()).slice(0, 500)}`,
      );
    }
    const payload = (await response.json()) as {
      data?: Record<string, unknown>;
    };
    if (!payload.data) throw new Error("OpenBao transit returned no data");
    return payload.data;
  }

  private async accessToken(): Promise<string> {
    if (this.token && (this.config.token || Date.now() < this.tokenExpiresAt)) {
      return this.token;
    }
    const response = await this.request(
      `${this.baseUrl}/v1/auth/approle/login`,
      {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          role_id: this.config.roleId,
          secret_id: this.config.secretId,
        }),
      },
    );
    if (!response.ok) {
      throw new Error(`OpenBao AppRole login failed (${response.status})`);
    }
    const payload = (await response.json()) as {
      auth?: { client_token?: unknown; lease_duration?: unknown };
    };
    if (typeof payload.auth?.client_token !== "string") {
      throw new Error("OpenBao AppRole returned no client token");
    }
    const leaseSeconds =
      typeof payload.auth.lease_duration === "number"
        ? payload.auth.lease_duration
        : 300;
    this.token = payload.auth.client_token;
    this.tokenExpiresAt =
      Date.now() + Math.max(30, leaseSeconds - 30) * 1_000;
    return this.token;
  }
}

