function safeIntegerHeader(
  raw: string | null,
  name: string,
  ceiling: number,
): number {
  const value = Number(raw);
  if (
    raw === null ||
    !Number.isSafeInteger(value) ||
    value <= 0 ||
    value > ceiling
  ) {
    throw new GatewayError(
      400,
      "invalid_request_error",
      `${name} must be a positive integer no greater than ${ceiling}.`,
      "invalid_header",
      name,
    );
  }
  return value;
}

function responseHeaders(upstream: Response): Headers {
  const headers = new Headers();
  for (const name of [
    "content-type",
    "content-length",
    "cache-control",
    "x-request-id",
    "x-portkey-trace-id",
  ]) {
    const value = upstream.headers.get(name);
    if (value) headers.set(name, value);
  }
  return headers;
}

function upstreamRequestId(upstream: Response): string | undefined {
  return (
    upstream.headers.get("x-request-id") ??
    upstream.headers.get("x-portkey-trace-id") ??
    undefined
  );
}

export function actualCostMicrousd(upstream: Response): number | undefined {
  const raw =
    upstream.headers.get("x-portkey-cost") ??
    upstream.headers.get("x-portkey-total-cost");
  if (!raw) return undefined;
  const usd = Number(raw);
  const microusd = Math.ceil(usd * 1_000_000);
  return Number.isSafeInteger(microusd) && microusd >= 0
    ? addProviderMarkup(microusd)
    : undefined;
}

async function pseudonym(
  accountId: string,
  secret: Uint8Array,
): Promise<string> {
  const key = await crypto.subtle.importKey(
    "raw",
    new Uint8Array(secret).buffer as ArrayBuffer,
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const digest = new Uint8Array(
    await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(accountId)),
  );
  return `nou_${Buffer.from(digest).toString("base64url").slice(0, 32)}`;
}

async function requestAlias(request: Request): Promise<string> {
  const contentType = request.headers.get("content-type") ?? "";
  try {
    if (contentType.includes("application/json")) {
      const value = (await request.clone().json()) as { model?: unknown };
      return typeof value.model === "string" ? value.model : "default";
    }
    if (
      contentType.includes("multipart/form-data") ||
      contentType.includes("application/x-www-form-urlencoded")
    ) {
      const value = await request.clone().formData();
      const model = value.get("model");
      return typeof model === "string" ? model : "default";
    }
  } catch {
    throw new GatewayError(
      400,
      "invalid_request_error",
      "The request body could not be parsed.",
      "invalid_body",
    );
  }
  return "default";
}

async function requestHash(request: Request): Promise<string> {
  const body = await request.clone().arrayBuffer();
  const digest = await crypto.subtle.digest("SHA-256", body);
  return Buffer.from(new Uint8Array(digest)).toString("base64url");
}

function readUsage(value: unknown, normalizeTextTokens = false): Usage | undefined {
  if (!value || typeof value !== "object") return undefined;
  const usage = (value as { usage?: unknown }).usage;
  if (!usage || typeof usage !== "object" || Array.isArray(usage)) return undefined;
  const result = usage as Usage;
  if (!normalizeTextTokens) return result;
  return {
    ...result,
    ...(result.input_tokens === undefined && typeof result.prompt_tokens === "number"
      ? { input_tokens: result.prompt_tokens } : {}),
    ...(result.output_tokens === undefined && typeof result.completion_tokens === "number"
      ? { output_tokens: result.completion_tokens } : {}),
  };
}

function microUsdToUsd(microusd: number): number {
  return Math.round(microusd) / 1_000_000;
}

async function expectsEventStream(input: MeteredProxyInput): Promise<boolean> {
  if (
    !["/chat/completions", "/responses"].includes(input.upstreamPath) ||
    !input.request.headers.get("content-type")?.includes("application/json")
