import { describe, expect, test } from "bun:test";
import { ConvexError } from "convex/values";
import { ConvexProviderStore } from "./convex-store";
import { OpenBaoTransit } from "./openbao";

function makeStore(mutationResult: unknown): ConvexProviderStore {
  const store = new ConvexProviderStore({
    convexUrl: "https://example.convex.cloud",
    gatewaySecret: "secret",
    transit: new OpenBaoTransit({ address: "https://openbao.test", token: "t" }),
    paddleApiKey: "paddle",
    paddleGrantPrograms: {},
  });
  // The Convex HTTP client isn't reachable in unit tests; stub the mutation
  // call directly to drive `reserve`'s status-mapping logic in isolation.
  (store as unknown as { convex: { mutation: () => Promise<unknown> } }).convex = {
    mutation: async () => {
      if (mutationResult instanceof Error) throw mutationResult;
      return mutationResult;
    },
  } as never;
  return store;
}

describe("ConvexProviderStore.reserve", () => {
  test("maps structured production funding errors even when the message is redacted", async () => {
    const input = {
      requestId: "req_production", idempotencyKey: "idem_production", accountId: "did:plc:alice",
      product: "keating" as const, feature: "chat", alias: "balanced", maxCostMicrousd: 100,
      pricingVersion: "current", requestHash: "hash",
    };
    for (const [code, publicCode] of [
      ["INSUFFICIENT_FUNDS", "insufficient_funds"],
      ["HOSTED_INFERENCE_BLOCKED_BY_DEBT", "outstanding_balance"],
    ]) {
      const error = new ConvexError(code!);
      error.message = "[Request ID: private-id] Server Error";
      await expect(makeStore(error).reserve(input)).rejects.toMatchObject({
        status: 402, type: "insufficient_quota", code: publicCode,
      });
    }
    const unexpected = new ConvexError("PRIVATE_DATABASE_FAILURE");
    await expect(makeStore(unexpected).reserve(input)).rejects.toBe(unexpected);
  });

  test("answers a stale session version as a revoked session, not a server error", async () => {
    const input = {
      requestId: "req_stale", idempotencyKey: "idem_stale", accountId: "did:plc:alice",
      product: "twyne" as const, feature: "chat", alias: "balanced", maxCostMicrousd: 100,
      pricingVersion: "current", requestHash: "hash",
    };
    const error = new ConvexError("session_revoked");
    error.message = "[Request ID: private-id] Server Error";
    await expect(makeStore(error).reserve(input)).rejects.toMatchObject({
      status: 401, type: "authentication_error", code: "session_revoked",
    });
  });

  test("reports funding failures as non-retryable billing errors without exposing Convex details", async () => {
    const input = {
      requestId: "req_unfunded", idempotencyKey: "idem_unfunded", accountId: "did:plc:alice",
      product: "keating" as const, feature: "chat", alias: "balanced", maxCostMicrousd: 100,
      pricingVersion: "current", requestHash: "hash",
    };
    for (const [upstreamCode, publicCode] of [
      ["INSUFFICIENT_FUNDS", "insufficient_funds"],
      ["HOSTED_INFERENCE_BLOCKED_BY_DEBT", "outstanding_balance"],
    ]) {
      const store = makeStore(new Error(`[Request ID: private-id] Server Error\nUncaught Error: ${upstreamCode}\n    at reserveFunds (wallet.ts:53)`));
      await expect(store.reserve(input)).rejects.toMatchObject({ status: 402, type: "insufficient_quota", code: publicCode });
    }
    const unexpected = new Error("Internal database error with private details");
    await expect(makeStore(unexpected).reserve(input)).rejects.toBe(unexpected);
  });

  test("proceeds when begin retried a terminal, unbilled request", async () => {
    // inference:begin retires the old lookup and returns a fresh reserved row
    // carrying the new requestId, so the retry is funded by a new reservation.
    const store = makeStore({ requestId: "req_new", state: "reserved" });
    const reservation = await store.reserve({
      requestId: "req_new",
      idempotencyKey: "idem_1",
      accountId: "did:plc:alice",
      product: "twyne",
      feature: "chat",
      alias: "fast",
      maxCostMicrousd: 100,
      pricingVersion: "current",
      requestHash: "hash",
    });
    expect(reservation.status).toBe("reserved");
  });

  test("conflicts on a 'failed' request that already billed", async () => {
    // fail() can settle a billable amount, so begin declines to retry these
    // and hands back the original row.
    const store = makeStore({ requestId: "req_old", state: "failed", billedMicros: 4_000 });
    const reservation = await store.reserve({
      requestId: "req_new",
      idempotencyKey: "idem_2",
      accountId: "did:plc:alice",
      product: "twyne",
      feature: "chat",
      alias: "fast",
      maxCostMicrousd: 100,
      pricingVersion: "current",
      requestHash: "hash",
    });
    expect(reservation.status).toBe("existing");
  });

  test("still conflicts on a genuinely in-flight 'running' request", async () => {
    const store = makeStore({ requestId: "req_old", state: "running" });
    const reservation = await store.reserve({
      requestId: "req_new",
      idempotencyKey: "idem_3",
      accountId: "did:plc:alice",
      product: "twyne",
      feature: "chat",
      alias: "fast",
      maxCostMicrousd: 100,
      pricingVersion: "current",
      requestHash: "hash",
    });
    expect(reservation.status).toBe("existing");
  });
});

