import { readFileSync, writeFileSync } from "node:fs";
import { createDpopFetch, issueNotOrganicAccessToken } from "/home/diogenes/Projects/apps/twyne/convex/lib/notorganic.ts";
const folder = "/home/diogenes/.cache/notorganic-runtime-release-20261023";
const issuer = "https://api.notorganic.info";
const did = "did:plc:h7t2qykaxwf6s7iez6pmhs45";
const prefix = "notorganic-release-20261023-compatible-score";
const evidence = JSON.parse(readFileSync(`${folder}/direct-score-evidence.json`, "utf8"));
const child = Bun.spawn(["rtk", "proxy", "bunx", "convex", "env", "get", "--prod", "NOTORGANIC_ASSERTION_PRIVATE_KEY"], { cwd: "/home/diogenes/Projects/apps/twyne", stdout: "pipe", stderr: "pipe", env: Object.fromEntries(Object.entries(process.env).filter(([name]) => !name.startsWith("CONVEX_"))) });
const [key, _stderr, code] = await Promise.all([new Response(child.stdout).text(), new Response(child.stderr).text(), child.exited]);
if (code !== 0) throw new Error("Credential read failed; output redacted.");
const token = await issueNotOrganicAccessToken({ did, feature: "judgement", capabilities: ["judgement:evaluate", "usage:read"], sessionVersion: 0 }, { NOTORGANIC_ENABLED: "true", NOTORGANIC_ISSUER: issuer, NOTORGANIC_AUDIENCE: "notorganic", NOTORGANIC_ASSERTION_PRIVATE_KEY: key.trim() });
const budget = JSON.parse(readFileSync(`${folder}/smoke-budget.json`, "utf8"));
if (budget.conservativelyCommittedMicrousd + 50_000 > budget.authorizedMicrousd) throw new Error("Smoke budget exhausted.");
budget.conservativelyCommittedMicrousd += 50_000;
budget.requests.push({ phase: "hosted-compatible-score", count: 5, maxCostMicrousd: 50_000, at: new Date().toISOString() });
writeFileSync(`${folder}/smoke-budget.json`, JSON.stringify(budget, null, 2) + "\n", { mode: 0o600 });
const authenticated = createDpopFetch(token, fetch);
const startedAt = new Date().toISOString();
const results = await Promise.all(evidence.results.map(async (sample: any, index: number) => {
  const response = await authenticated(`${issuer}/v1/judgement`, { method: "POST", headers: { "content-type": "application/json", "x-notorganic-product": "twyne", "x-notorganic-feature": "judgement", "idempotency-key": `${prefix}-${index}`, "x-notorganic-max-cost-microusd": "10000" }, body: JSON.stringify({ ...sample.input, model: "judgement-jev" }), signal: AbortSignal.timeout(45_000) });
  const body = await response.json() as any;
  return { index, status: response.status, model: body.model, answers: body.answers, usage: body.usage, error: body.error ? { code: body.error.code, type: body.error.type } : undefined };
}));
const usageResponse = await authenticated(`${issuer}/v1/usage?limit=100`, { headers: { "x-notorganic-product": "twyne", "x-notorganic-feature": "judgement" }, signal: AbortSignal.timeout(15_000) });
const usage = await usageResponse.json() as any;
const rows = (usage.data ?? []).filter((row: any) => String(row.idempotencyKey).startsWith(prefix));
const report = { startedAt, finishedAt: new Date().toISOString(), concurrentRequests: 5, results, ledger: { status: usageResponse.status, rows: rows.map((row: any) => ({ requestId: row.requestId, idempotencyKey: row.idempotencyKey, state: row.state, billedMicros: row.billedMicros, reconciliationReason: row.reconciliationReason })), billedMicros: rows.reduce((sum: number, row: any) => sum + (row.billedMicros ?? 0), 0) }, success: results.every((result: any) => result.status === 200 && result.answers?.value?.type === "score" && result.answers?.grounded?.type === "noul") && rows.length === 5 && rows.every((row: any) => row.state === "succeeded" && !row.reconciliationReason), conservativelyCommittedMicrousd: budget.conservativelyCommittedMicrousd };
writeFileSync(`${folder}/hosted-score-batch.json`, JSON.stringify(report, null, 2) + "\n", { mode: 0o600 });
console.log(JSON.stringify(report, null, 2));
if (!report.success) process.exitCode = 1;

